/**
 * Responsive Invoice Card item
 * @param {Object} invoice - Invoice object
 * @param {string} currencySymbol - e.g. "₹"
 * @param {Function} onView - View callback
 * @param {Function} onEdit - Edit callback
 * @param {Function} onDelete - Delete callback
 * @param {Function} onDownload - Download PDF callback
 */
const InvoiceCard = ({ invoice, currencySymbol = '₹', businessSettings = {}, compact = false, onView, onEdit, onDelete, onDownload, onRestore, onDownloadBackup, isDeleted }) => {
  if (!invoice) return null;
  const [showShareMenu, setShowShareMenu] = useState(false);
  const menuRef = useRef(null);

  // Close sharing popover on click outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setShowShareMenu(false);
      }
    };
    if (showShareMenu) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showShareMenu]);

  const getSyncStatusStyle = (status) => {
    switch (status) {
      case 'synced':
        return 'bg-theme-accent-light text-theme-accent border-theme-border-soft dark:bg-theme-accent-light/20 dark:text-theme-accent dark:border-theme-accent/30';
      case 'pending':
        return 'bg-theme-warning/5 text-theme-warning border-amber-100 dark:bg-amber-950/20 dark:text-amber-400 dark:border-amber-900/30';
      case 'failed':
        return 'bg-theme-danger/5 text-theme-danger border-rose-100 dark:bg-rose-950/20 dark:text-theme-danger dark:border-rose-900/30';
      case 'offline':
        return 'bg-theme-accent-light text-theme-accent border-theme-border-soft dark:bg-sky-950/20 dark:text-theme-accent dark:border-sky-900/30';
      default:
        return 'bg-theme-app dark:bg-theme-surface text-theme-muted border-theme-border-soft dark:border-theme-border-soft dark:bg-theme-app/20 dark:text-theme-muted dark:border-theme-border-soft/30';
    }
  };

  const getSyncStatusLabel = (status) => {
    switch (status) {
      case 'synced': return 'Saved to Cloud';
      case 'pending': return 'Pending Sync';
      case 'failed': return 'Sync Failed';
      case 'offline': return 'Offline Draft';
      default: return '';
    }
  };

  const getStatusStyle = (status) => {
    switch (status) {
      case 'Paid':
        return 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-900/50';
      case 'Payment Submitted':
      case 'Payment Submitted / Pending Verification':
        return 'bg-purple-50 text-purple-700 border-purple-100 dark:bg-theme-accent-light dark:text-purple-400 dark:border-purple-900/30';
      case 'Partially Paid':
      case 'Partial':
        return 'bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-950/40 dark:text-amber-400 dark:border-amber-900/50';
      case 'Overdue':
        return 'bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-950/40 dark:text-rose-400 dark:border-rose-900/50';
      case 'Cancelled':
        return 'bg-theme-surface dark:bg-theme-card text-theme-muted border-theme-border-soft dark:bg-theme-card dark:text-theme-muted dark:border-theme-border-soft/30';
      case 'Unpaid':
      case 'Pending':
      default:
        return 'bg-theme-app text-theme-secondary border-theme-border-soft dark:bg-theme-surface/60 dark:text-theme-primary dark:border-theme-border-strong/50';
    }
  };

  const getOrderStatusStyle = (status) => {
    switch (status) {
      case 'Delivered':
        return 'bg-theme-accent-light text-theme-accent border-theme-border-soft dark:bg-theme-accent-light/20 dark:text-theme-accent dark:border-theme-accent/30';
      case 'Ready':
        return 'bg-theme-accent-light text-theme-accent border-theme-border-soft dark:bg-theme-accent/10 dark:text-theme-accent dark:border-theme-accent/30';
      case 'In Progress':
        return 'bg-theme-accent-light text-theme-accent border-theme-border-soft dark:bg-theme-accent/10 dark:text-theme-accent dark:border-theme-accent/30';
      case 'Cancelled':
        return 'bg-theme-danger/5 text-rose-700 border-rose-100 dark:bg-rose-950/20 dark:text-theme-danger dark:border-rose-900/30';
      case 'Pending':
      default:
        return 'bg-theme-warning/5 text-amber-700 border-amber-100 dark:bg-amber-950/20 dark:text-amber-400 dark:border-amber-900/30';
    }
  };

  return (
    <div className="bg-theme-card dark:bg-theme-card rounded-2xl p-5 md:p-5 border border-theme-border-soft dark:border-theme-border-soft/80 shadow-premium hover:shadow-premium-hover transition-all duration-300">
      <div className={`flex flex-col ${compact ? '' : 'md:flex-row md:items-center'} justify-between gap-4`}>
        {/* Top/Left Section: Metadata */}
        <div className="flex items-center gap-3">
          <div className="p-3 bg-gradient-to-br from-theme-app to-theme-surface dark:from-theme-surface dark:to-theme-card text-theme-accent dark:text-theme-accent rounded-xl border border-theme-border-soft shadow-sm hidden sm:block">
            <FileText className="w-6 h-6" />
          </div>
          <div>
            <div className="flex flex-wrap items-center gap-2">
              <span className="font-black text-theme-primary dark:text-theme-primary text-base md:text-lg">{invoice.invoiceNumber}</span>
              {invoice.customerName && (
                <>
                   <span className="text-theme-muted hidden sm:inline">•</span>
                   <span className="font-extrabold text-theme-accent dark:text-theme-accent text-sm md:text-base bg-theme-accent/5 px-2 py-0.5 rounded-lg border border-theme-accent/10">{invoice.customerName}</span>
                </>
              )}
            </div>
            <div className="flex flex-wrap items-center gap-1.5 mt-2">
              <span className={`text-[10px] px-2.5 py-0.5 rounded-full border font-extrabold uppercase tracking-wider shadow-sm ${getStatusStyle(invoice.paymentStatus)}`}>
                {invoice.paymentStatus}
              </span>
              {invoice.orderStatus && (
                <span className={`text-[10px] px-2.5 py-0.5 rounded-full border font-extrabold uppercase tracking-wider shadow-sm ${getOrderStatusStyle(invoice.orderStatus)}`}>
                  {invoice.orderStatus}
                </span>
              )}
              {invoice.syncStatus && getSyncStatusLabel(invoice.syncStatus) && (
                <span className={`text-[10px] px-2.5 py-0.5 rounded-full border font-extrabold uppercase tracking-wider shadow-sm ${getSyncStatusStyle(invoice.syncStatus)}`}>
                  {getSyncStatusLabel(invoice.syncStatus)}
                </span>
              )}
            </div>
            <p className="text-[11px] font-bold text-theme-muted dark:text-theme-muted mt-2">Due Date: {invoice.dueDate || 'N/A'}</p>
          </div>
        </div>

        {/* Right Section: Price & Quick CTA Buttons */}
        <div className={`flex ${compact ? 'flex-col items-start border-t pt-3' : 'md:flex-col items-start md:items-end justify-between border-t md:border-t-0 pt-3 md:pt-0 gap-3'} border-theme-border-soft dark:border-theme-border-soft/80`}>
          
          {/* Pro+ Payment Stats Bar */}
          <div className="flex items-center gap-3 bg-theme-app dark:bg-theme-surface rounded-xl px-3 py-2 border border-theme-border-soft dark:border-theme-border-soft/50 shadow-inner w-full md:w-auto overflow-x-auto no-scrollbar">
            <div className="flex flex-col items-start md:items-end min-w-[70px]">
              <span className="text-[9px] text-theme-muted font-bold uppercase tracking-wider">Bill Total</span>
              <span className="text-sm font-black text-theme-primary dark:text-theme-primary">{formatCurrency(invoice.grandTotal, currencySymbol)}</span>
            </div>
            <div className="w-px h-6 bg-theme-border-soft dark:bg-theme-border-soft/50"></div>
            <div className="flex flex-col items-start md:items-end min-w-[70px]">
              <span className="text-[9px] text-theme-muted font-bold uppercase tracking-wider">Paid</span>
              <span className="text-sm font-black text-emerald-600 dark:text-emerald-400">{formatCurrency(invoice.amountPaid || 0, currencySymbol)}</span>
            </div>
            <div className="w-px h-6 bg-theme-border-soft dark:bg-theme-border-soft/50"></div>
            <div className="flex flex-col items-start md:items-end min-w-[70px]">
              <span className="text-[9px] text-theme-muted font-bold uppercase tracking-wider">Due</span>
              <span className={`text-sm font-black ${invoice.balanceDue > 0 ? 'text-rose-500' : 'text-theme-muted'}`}>{formatCurrency(invoice.balanceDue || 0, currencySymbol)}</span>
            </div>
          </div>

          <div className="flex items-center gap-2 mt-2">
            {!isDeleted && (
              <>
                <button
                  onClick={() => onView(invoice)}
                  title="Preview Invoice"
                  className="p-2 text-theme-muted dark:text-theme-muted hover:text-theme-accent dark:hover:text-theme-accent hover:bg-theme-accent-light dark:hover:bg-theme-accent-light rounded-xl transition-all cursor-pointer"
                >
                  <Eye className="w-4 h-4" />
                </button>
                {invoice.paymentStatus !== 'Paid' && (
                  <button
                    onClick={() => onEdit(invoice)}
                    title="Edit Invoice"
                    className="p-2 text-theme-muted dark:text-theme-muted hover:text-theme-accent dark:hover:text-theme-accent hover:bg-theme-accent-light dark:hover:bg-theme-accent-light rounded-xl transition-all cursor-pointer"
                  >
                    <Edit2 className="w-4 h-4" />
                  </button>
                )}
                <button
                  onClick={() => onDownload(invoice)}
                  title="Download PDF"
                  className="p-2 text-theme-muted dark:text-theme-muted hover:text-theme-accent dark:hover:text-theme-accent hover:bg-theme-accent-light dark:hover:bg-theme-accent-light/30 rounded-xl transition-all cursor-pointer"
                >
                  <Download className="w-4 h-4" />
                </button>

                {/* Quick Share Popover Dropdown */}
                <div className="relative flex" ref={menuRef}>
                  <button
                    onClick={() => setShowShareMenu(!showShareMenu)}
                    title="Share Invoice"
                    className={`p-2 rounded-xl transition-all cursor-pointer flex items-center justify-center ${showShareMenu
                      ? 'text-theme-accent bg-theme-accent-light dark:text-theme-accent dark:bg-theme-accent-light'
                      : 'text-theme-muted dark:text-theme-muted hover:text-theme-accent dark:hover:text-theme-accent hover:bg-theme-accent-light dark:hover:bg-theme-accent-light'
                      }`}
                  >
                    <Share2 className="w-4 h-4" />
                  </button>

                  <AnimatePresence>
                    {showShareMenu && (
                      <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 10 }}
                        transition={{ duration: 0.15 }}
                        className="absolute right-0 bottom-full mb-2 w-48 bg-theme-card dark:bg-theme-card/95 dark:bg-theme-card/95 backdrop-blur-md border border-theme-border-soft dark:border-theme-border-soft rounded-2xl p-2 shadow-2xl z-20 flex flex-col gap-1 text-[11px]"
                      >
                        <div className="px-3 py-1 font-black text-[9px] text-theme-muted dark:text-theme-muted uppercase tracking-wider border-b border-theme-border-soft dark:border-theme-border-soft/60 mb-1">
                          Quick Share
                        </div>

                        <button
                          onClick={async () => {
                            try {
                              const customerId = invoice.customerId || invoice.customer?.id;
                              if (!customerId) {
                                toast.error('Please assign a customer to share the Portal.');
                                return;
                              }
                              const updatedInvoice = { ...invoice };
                              const link = generateWhatsAppShareLink(updatedInvoice, currencySymbol, businessSettings);
                              window.open(link, '_blank');
                              setShowShareMenu(false);
                            } catch (err) {
                              toast.error(err.message || 'Could not create live link. Please try again.');
                            }
                          }}
                          className="flex items-center gap-2 px-3 py-2 text-theme-primary dark:text-theme-muted hover:bg-theme-accent-light dark:hover:bg-theme-accent-light/20 hover:text-theme-accent dark:hover:text-theme-accent rounded-xl transition-colors font-bold w-full text-left cursor-pointer"
                        >
                          <WhatsAppIcon className="w-3.5 h-3.5 text-theme-accent" />
                          <span>WhatsApp Share</span>
                        </button>

                        {invoice.paymentStatus !== 'Paid' && (
                          <button
                            onClick={async () => {
                              try {
                                const customerId = invoice.customerId || invoice.customer?.id;
                                if (!customerId) {
                                  toast.error('Please assign a customer to share the Portal.');
                                  return;
                                }
                                const updatedInvoice = { ...invoice };
                                const link = generateWhatsAppReminderLink(updatedInvoice, currencySymbol, businessSettings);
                                window.open(link, '_blank');
                                setShowShareMenu(false);
                              } catch (err) {
                                toast.error('Could not create live link. Please try again.');
                              }
                            }}
                            className="flex items-center gap-2 px-3 py-2 text-theme-primary dark:text-theme-muted hover:bg-theme-danger/5 dark:hover:bg-rose-950/20 hover:text-rose-700 dark:hover:text-theme-danger rounded-xl transition-colors font-bold w-full text-left cursor-pointer"
                          >
                            <WhatsAppIcon className="w-3.5 h-3.5 text-theme-danger" />
                            <span>Send Reminder</span>
                          </button>
                        )}

                        <button
                          onClick={async () => {
                            try {
                              const customerId = invoice.customerId || invoice.customer?.id;
                              if (!customerId) {
                                toast.error('Please assign a customer to share the Portal.');
                                return;
                              }
                              const updatedInvoice = { ...invoice };
                              const { mailto } = generateEmailShareLink(updatedInvoice, currencySymbol, businessSettings);
                              window.open(mailto, '_blank');
                              setShowShareMenu(false);
                            } catch (err) {
                              toast.error(err.message || 'Could not create live link. Please try again.');
                            }
                          }}
                          className="flex items-center gap-2 px-3 py-2 text-theme-primary dark:text-theme-muted hover:bg-theme-accent-light dark:hover:bg-sky-950/20 hover:text-theme-accent dark:hover:text-theme-accent rounded-xl transition-colors font-bold w-full text-left cursor-pointer"
                        >
                          <Mail className="w-3.5 h-3.5 text-theme-accent" />
                          <span>Email Invoice</span>
                        </button>

                        <button
                          onClick={async () => {
                            const isLiveLinkEnabled = businessSettings?.customerLiveLinkSettings?.enableLiveInvoiceLink !== false;
                            if (!isLiveLinkEnabled) {
                              toast.error('Live Link is disabled. Enable it from Settings.');
                              return;
                            }
                            try {
                              const customerId = invoice.customerId || invoice.customer?.id;
                              if (!customerId) {
                                toast.error('Please assign a customer to share the Portal.');
                                return;
                              }
                              const isEdu = isEducationCategory(businessSettings?.businessCategory);
                              const portalPath = isEdu ? '/student-portal' : '/portal';
                              const liveLink = `${window.location.origin}${portalPath}/${customerId}`;
                              await navigator.clipboard.writeText(liveLink);
                              toast.success('Live Invoice Link copied to clipboard!');
                              setShowShareMenu(false);
                            } catch (err) {
                              toast.error(err.message || 'Could not create live link. Please try again.');
                            }
                          }}
                          className="flex items-center gap-2 px-3 py-2 text-theme-primary dark:text-theme-muted hover:bg-theme-accent-light dark:hover:bg-theme-accent-light hover:text-theme-accent dark:hover:text-theme-accent rounded-xl transition-colors font-bold w-full text-left cursor-pointer"
                        >
                          <Link className="w-3.5 h-3.5 text-theme-accent" />
                          <span>Copy Live Link</span>
                        </button>

                        <button
                          onClick={async () => {
                            try {
                              const customerId = invoice.customerId || invoice.customer?.id;
                              if (!customerId) {
                                toast.error('Please assign a customer to share the Portal.');
                                return;
                              }
                              const updatedInvoice = { ...invoice };
                              const text = generateInvoiceShareText(updatedInvoice, currencySymbol, businessSettings);
                              await navigator.clipboard.writeText(text);
                              toast.success('Invoicing summary copied to clipboard!');
                              setShowShareMenu(false);
                            } catch (err) {
                              toast.error(err.message || 'Could not create live link. Please try again.');
                            }
                          }}
                          className="flex items-center gap-2 px-3 py-2 text-theme-primary dark:text-theme-muted hover:bg-theme-warning/5 dark:hover:bg-amber-950/20 hover:text-amber-700 dark:hover:text-amber-400 rounded-xl transition-colors font-bold w-full text-left cursor-pointer"
                        >
                          <Copy className="w-3.5 h-3.5 text-theme-warning" />
                          <span>Copy Summary</span>
                        </button>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              </>
            )}

            {isDeleted && onRestore && (
              <button
                onClick={() => onRestore(invoice.id)}
                title="Restore Invoice"
                className="text-xs font-bold px-3 py-1.5 bg-theme-accent-light text-theme-accent hover:bg-theme-accent-light rounded-lg transition-all"
              >
                Restore
              </button>
            )}

            {!isDeleted && onDownloadBackup && (
              <button
                onClick={() => onDownloadBackup()}
                title="Download Editable Backup (.billqyro)"
                className="p-2 text-theme-muted hover:text-theme-accent hover:bg-theme-accent-light rounded-xl transition-all"
              >
                <Download className="w-4 h-4" />
              </button>
            )}

            {invoice.paymentStatus !== 'Paid' && (
              <button
                onClick={() => onDelete(invoice.id)}
                title={isDeleted ? "Permanently Delete" : "Move to Trash"}
                className="p-2 text-theme-muted dark:text-theme-muted hover:text-theme-danger dark:hover:text-theme-danger hover:bg-theme-danger/5 dark:hover:bg-rose-950/30 rounded-xl transition-all cursor-pointer"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            )}
            
            {!isDeleted && invoice.syncStatus === 'failed' && (
              <button
                onClick={() => {
                  toast.loading('Retrying sync...', { id: 'retrySync' });
                  import('../services/invoiceEngine').then(m => m.invoiceEngine.retrySync(invoice.id)).then(res => {
                    toast.dismiss('retrySync');
                  });
                }}
                title={`Retry Sync. Error: ${invoice.syncError || 'Unknown'}`}
                className="p-2 text-theme-danger dark:text-theme-danger hover:text-white dark:hover:text-white hover:bg-rose-600 dark:hover:bg-rose-600 rounded-xl transition-all cursor-pointer flex items-center gap-1"
              >
                <RefreshCw className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default React.memo(InvoiceCard, (prevProps, nextProps) => {
  return (
    prevProps.invoice?.updatedAt === nextProps.invoice?.updatedAt &&
    prevProps.invoice?.paymentStatus === nextProps.invoice?.paymentStatus &&
    prevProps.isDeleted === nextProps.isDeleted
  );
});

import React from 'react';
import DynamicQRCode from './DynamicQRCode';
import { formatCurrency } from '../utils/invoiceUtils';
import { getInvoiceColumns, getItemValue } from '../utils/invoiceSchema';
import { ShieldCheck, Calendar, Hash, FileText } from 'lucide-react';
import { getCategoryWording } from '../config/businessPresets';

/**
 * High-fidelity Printable Invoice Letterhead Layout
 * @param {Object} invoice - Invoice object
 * @param {Object} businessSettings - Company's active profile settings
 */
const InvoicePreview = ({ invoice, businessSettings }) => {
  if (!invoice) return null;

  const templateId = businessSettings?.selectedPdfTemplate || 'classic';

  // Destructure Snapshots with Fallbacks
  const regionalPrefs = invoice.regionalSettingsSnapshot || {
    country: businessSettings?.country || 'India',
    currency: businessSettings?.currency || '₹',
    currencyCode: businessSettings?.currencyCode || 'INR',
    language: businessSettings?.language || 'English',
    taxLabel: businessSettings?.taxLabel || 'GST',
    dateFormat: businessSettings?.dateFormat || 'DD/MM/YYYY',
    numberFormat: businessSettings?.numberFormat || 'Indian'
  };

  const paymentPrefs = invoice.paymentSettingsSnapshot || {
    paymentQrEnabled: businessSettings?.paymentQrEnabled || false,
    paymentMethod: businessSettings?.paymentMethod || 'Manual',
    upiId: businessSettings?.upiId || '',
    bkashNumber: businessSettings?.bkashNumber || '',
    nagadNumber: businessSettings?.nagadNumber || '',
    rocketNumber: businessSettings?.rocketNumber || '',
    payeeName: businessSettings?.payeeName || businessSettings?.businessName || '',
    paymentNote: businessSettings?.paymentNote || '',
    customPaymentLink: businessSettings?.customPaymentLink || '',
    showQrInPreview: businessSettings?.showQrInPreview !== undefined ? businessSettings?.showQrInPreview : true
  };

  const businessPrefs = invoice.businessSnapshot || {
    businessName: businessSettings?.businessName || 'BillQyro Store',
    logoUrl: businessSettings?.logoUrl || '',
    ownerName: businessSettings?.ownerName || 'Manager',
    phone: businessSettings?.phone || '',
    whatsapp: businessSettings?.whatsapp || '',
    email: businessSettings?.email || '',
    address: businessSettings?.address || '',
    gstNumber: businessSettings?.gstNumber || '',
    currency: businessSettings?.currency || '₹',
    taxLabel: businessSettings?.taxLabel || 'GST'
  };

  const currencySymbol = regionalPrefs.currency || '₹';

  const getStatusBadgeStyle = (status) => {
    switch (status) {
      case 'Paid':
        return 'bg-theme-accent-light text-theme-primary border-theme-border-soft dark:bg-theme-accent-light/20 dark:text-theme-accent dark:border-theme-accent/30';
      case 'Pending':
        return 'bg-theme-warning/5 text-amber-800 border-theme-warning/30 dark:bg-amber-950/20 dark:text-amber-400 dark:border-amber-900/30';
      case 'Unpaid':
      default:
        return 'bg-theme-danger/5 text-rose-800 border-theme-danger/30 dark:bg-rose-950/20 dark:text-theme-danger dark:border-rose-900/30';
    }
  };

  const steps = ['Pending', 'In Progress', 'Ready', 'Delivered'];
  const isCancelled = invoice.orderStatus === 'Cancelled';
  
  const getStepIndex = (status) => {
    switch (status) {
      case 'Pending': return 0;
      case 'In Progress': return 1;
      case 'Ready': return 2;
      case 'Delivered': return 3;
      default: return 0;
    }
  };

  const currentStepIdx = getStepIndex(invoice.orderStatus);

  const billType = invoice.billType || 'default';
  const categoryWords = getCategoryWording(billType);

  return (
    <div 
      id="invoice-preview-capture" 
      className={`bg-theme-card dark:bg-theme-card border ${templateId === 'minimal' ? 'border-black rounded-none shadow-none' : 'border-theme-border-soft dark:border-theme-border-soft rounded-3xl shadow-premium'} p-6 md:p-10 max-w-4xl mx-auto text-theme-primary dark:text-theme-primary transition-all duration-300 relative overflow-hidden`}
      style={{ fontFamily: "'Inter', sans-serif" }}
    >
      {/* 0. ORDER TRACKING TIMELINE STEPPER */}
      {invoice.orderStatus && (
        <div className="mb-8 p-4 md:p-5 bg-theme-app dark:bg-theme-surface dark:bg-theme-app/40 border border-theme-border-soft dark:border-theme-border-soft/80 dark:border-theme-border-soft/80 rounded-2xl">
          <div className="flex items-center justify-between mb-3">
            <span className="text-[10px] uppercase font-black tracking-wider text-theme-muted dark:text-theme-muted">Order Dispatch Progress</span>
            {isCancelled ? (
              <span className="text-[10px] px-2.5 py-0.5 rounded-full border bg-theme-danger/5 text-rose-700 border-rose-100 dark:bg-rose-950/20 dark:text-theme-danger dark:border-rose-900/30 font-extrabold uppercase tracking-wider animate-pulse">
                Cancelled
              </span>
            ) : (
              <span className="text-[10px] px-2.5 py-0.5 rounded-full border bg-theme-accent-light text-theme-accent border-theme-border-soft dark:bg-theme-accent/10 dark:text-theme-accent dark:border-theme-accent/30 font-extrabold uppercase tracking-wider">
                {invoice.orderStatus}
              </span>
            )}
          </div>

          {!isCancelled && (
            <div className="relative flex items-center justify-between w-full mt-4 pb-2">
              {/* Stepper Progress Bar Background */}
              <div className="absolute top-1/2 left-0 right-0 h-1 bg-theme-border-soft dark:bg-theme-card -translate-y-1/2 z-0 rounded-full"></div>
              
              {/* Stepper Active Progress Line */}
              <div 
                className="absolute top-1/2 left-0 h-1 bg-gradient-to-r from-[var(--accent)] to-[var(--accent-dark)] -translate-y-1/2 z-0 rounded-full transition-all duration-500"
                style={{ width: `${(currentStepIdx / (steps.length - 1)) * 100}%` }}
              ></div>

              {/* Step Nodes */}
              {steps.map((step, idx) => {
                const isCompleted = idx < currentStepIdx;
                const isActive = idx === currentStepIdx;
                
                return (
                  <div key={step} className="flex flex-col items-center relative z-10">
                    {/* Node Dot */}
                    <div 
                      className={`w-5.5 h-5.5 rounded-full flex items-center justify-center font-bold text-[9px] border transition-all duration-300 ${
                        isCompleted 
                          ? 'bg-theme-accent border-theme-accent text-white shadow-sm' 
                          : isActive 
                          ? 'bg-theme-accent border-theme-accent text-white scale-110 shadow' 
                          : 'bg-theme-card dark:bg-theme-card border-theme-border-soft dark:border-theme-border-soft text-theme-muted dark:text-theme-muted'
                      }`}
                    >
                      {idx + 1}
                    </div>
                    {/* Node Label */}
                    <span 
                      className={`text-[9px] font-bold mt-1.5 tracking-tight ${
                        isCompleted 
                          ? 'text-theme-accent dark:text-theme-accent' 
                          : isActive 
                          ? 'text-theme-accent dark:text-theme-accent font-extrabold' 
                          : 'text-theme-muted dark:text-theme-muted font-semibold'
                      }`}
                    >
                      {step}
                    </span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* 1. BRAND HEADER & METADATA GRID */}
      <div className={`flex flex-col md:flex-row justify-between items-start gap-6 border-b pb-8 ${templateId === 'modern' ? 'bg-slate-900 text-slate-200 -mx-6 -mt-6 md:-mx-10 md:-mt-10 p-6 md:p-10 rounded-t-3xl border-slate-800' : templateId === 'minimal' ? 'border-black' : 'border-theme-border-soft dark:border-theme-border-soft'}`}>
        {/* Left Side: Business logo & details */}
        <div>
          <div className="flex items-center gap-3">
            {businessPrefs?.logoUrl ? (
              <img
                src={businessPrefs.logoUrl}
                alt="Business Logo"
                className={`w-12 h-12 object-cover shadow-sm bg-theme-app dark:bg-theme-surface border ${templateId === 'minimal' ? 'rounded-none border-black' : 'rounded-xl border-theme-border-soft dark:border-theme-border-soft'}`}
              />
            ) : (
              <div className={`w-12 h-12 bg-gradient-to-tr from-theme-accent to-theme-accent-dark flex items-center justify-center text-white font-extrabold text-lg ${templateId === 'minimal' ? 'rounded-none' : 'rounded-xl'}`}>
                {businessPrefs?.businessName?.charAt(0) || 'B'}
              </div>
            )}
            <div>
              <h3 className={`font-extrabold text-xl tracking-tight ${templateId === 'modern' ? 'text-white' : 'text-theme-primary dark:text-theme-primary'}`}>{businessPrefs?.businessName || 'BillQyro Client'}</h3>
              {businessPrefs?.gstNumber && (
                <p className="text-xs text-theme-muted dark:text-theme-muted font-semibold uppercase tracking-wider mt-0.5">{regionalPrefs.taxLabel || 'GST'}: {businessPrefs.gstNumber}</p>
              )}
            </div>
          </div>
          
          <div className="mt-4 space-y-1 text-xs text-theme-muted dark:text-theme-muted font-medium max-w-sm leading-relaxed">
            <p>{businessPrefs?.address || 'Company Address Not Set'}</p>
            <p>Phone: {businessPrefs?.phone}</p>
            <p>Email: {businessPrefs?.email}</p>
          </div>
        </div>

        {/* Right Side: Invoice Info */}
        <div className="flex flex-col items-start md:items-end justify-start md:text-right gap-3">
          <div className="flex items-center gap-2">
            <span className={`text-xs px-3 py-1 rounded-full border font-bold ${getStatusBadgeStyle(invoice.paymentStatus)}`}>
              {invoice.paymentStatus}
            </span>
          </div>
          
          <div className="space-y-1 text-xs font-semibold text-theme-muted dark:text-theme-muted">
            <div className="flex flex-col md:items-end gap-1.5">
              <div className="flex items-center gap-1.5 justify-start md:justify-end text-theme-primary dark:text-theme-secondary text-sm">
                <Hash className="w-3.5 h-3.5 text-theme-accent" />
                <span>Invoice: <strong className="font-extrabold">{invoice.invoiceNumber}</strong></span>
              </div>
              {templateId === 'retail' && (
                <div className="px-3 py-1 bg-white border border-slate-200 rounded text-center text-slate-800 hidden md:block">
                  <div className="font-mono text-[8px] tracking-[0.3em] font-bold opacity-80 leading-none mb-0.5">||| |||| || |||</div>
                  <div className="text-[7px] uppercase tracking-widest font-black leading-none opacity-50">{invoice.invoiceNumber}</div>
                </div>
              )}
            </div>
            <div className="flex items-center gap-1.5 justify-start md:justify-end">
              <Calendar className="w-3.5 h-3.5 text-theme-muted dark:text-theme-muted" />
              <span>Date: {invoice.date}</span>
            </div>
            <div className="flex items-center gap-1.5 justify-start md:justify-end">
              <Calendar className="w-3.5 h-3.5 text-theme-muted dark:text-theme-muted" />
              <span className="text-theme-danger dark:text-theme-danger">Due Date: {invoice.dueDate}</span>
            </div>
          </div>
        </div>
      </div>

      {/* 2. CLIENT CRM GRID */}
      <div className={`grid grid-cols-1 md:grid-cols-2 gap-6 py-8 border-b text-xs ${templateId === 'minimal' ? 'border-black' : 'border-theme-border-soft dark:border-theme-border-soft'}`}>
        <div>
          <span className="font-bold text-theme-muted dark:text-theme-muted uppercase tracking-wider block mb-2">{templateId === 'teacher' ? 'Student Details' : 'Billed To'}</span>
          <h4 className="font-extrabold text-sm text-theme-primary dark:text-theme-primary dark:text-theme-primary">{invoice.customerName}</h4>
          
          {templateId === 'doctor' && (
            <div className="mt-3 p-3 bg-teal-50 dark:bg-teal-900/20 border-l-2 border-teal-500 rounded-r-md mb-2">
              <p className="font-bold text-teal-800 dark:text-teal-300 mb-1 flex items-center gap-1.5"><ShieldCheck className="w-3.5 h-3.5"/> Patient Details</p>
              <div className="space-y-0.5 text-[10px] text-teal-700 dark:text-teal-400 font-medium">
                <p>Name: {invoice.customerName}</p>
                {invoice.orderNotes && <p>Diagnosis/Ref: {invoice.orderNotes}</p>}
              </div>
            </div>
          )}
          <div className="text-theme-muted dark:text-theme-muted space-y-1 mt-2 max-w-xs leading-relaxed font-medium">
            <p>{invoice.customerAddress || 'No address provided'}</p>
            <p>Phone: {invoice.customerPhone || 'N/A'}</p>
            <p>Email: {invoice.customerEmail || 'N/A'}</p>
          </div>
        </div>
        
        <div className="md:text-right">
          {templateId === 'repair' && invoice.orderNotes ? (
            <>
              <span className="font-bold text-theme-muted dark:text-theme-muted uppercase tracking-wider block mb-2">Device & Job Notes</span>
              <div className="flex md:justify-end">
                <p className="font-medium text-theme-primary leading-relaxed bg-amber-50 dark:bg-amber-900/20 p-3 rounded-lg border border-amber-200 dark:border-amber-700/30 text-amber-900 dark:text-amber-200 text-left text-xs max-w-xs w-full">
                  {invoice.orderNotes}
                </p>
              </div>
            </>
          ) : (
            <>
              <span className="font-bold text-theme-muted dark:text-theme-muted uppercase tracking-wider block mb-2">Payment Terms</span>
              <p className="font-semibold text-theme-primary dark:text-theme-muted dark:text-theme-muted leading-relaxed">
                Please pay online on or before the due date.<br />
                Amounts are calculated in <strong className="text-theme-accent dark:text-theme-accent font-extrabold">{currencySymbol}</strong>.
              </p>
            </>
          )}
        </div>
      </div>

      {/* 3. ITEM TABLE (DYNAMIC SYNC) */}
      <div className="py-6 overflow-x-auto no-scrollbar">
        <table className="w-full text-left text-xs border-collapse">
          <thead>
            <tr className="border-b border-theme-border-soft dark:border-theme-border-soft text-theme-muted dark:text-theme-muted font-bold uppercase tracking-wider">
              {getInvoiceColumns(invoice, businessSettings).map(col => (
                <th key={col.id} className={`pb-3 text-${col.align}`} style={{ width: col.width }}>
                  {col.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 dark:divide-slate-800/40">
            {invoice.items && invoice.items.map((item, idx) => (
              <tr key={idx} className="text-theme-primary dark:text-theme-muted hover:bg-theme-app dark:bg-theme-surface/50 dark:hover:bg-theme-card/20">
                {getInvoiceColumns(invoice, businessSettings).map(col => {
                  if (col.id === 'sn') return <td key={col.id} className={`py-4 text-${col.align} text-theme-muted font-bold`}>{idx + 1}</td>;
                  
                  const val = getItemValue(item, col.id, invoice.billType);
                  
                  // Primary Column 1 gets slightly richer UI in preview
                  if (col.id === 'col1') {
                    return (
                      <td key={col.id} className={`py-4 font-semibold text-theme-primary dark:text-theme-primary dark:text-theme-secondary text-${col.align}`}>
                        <div className="flex flex-wrap items-center gap-2 mb-1">
                          {item.designNo && item.designNo !== 'N/A' && (
                            <span className="inline-block px-2 py-0.5 bg-theme-accent-light dark:bg-theme-accent-light text-theme-accent dark:text-theme-accent rounded text-[9px] font-black tracking-wider uppercase border border-theme-border-soft/10">
                              {item.designNo}
                            </span>
                          )}
                          {item.workType && (
                            <span className={`inline-block px-2 py-0.5 rounded text-[9px] font-bold ${(templateId === 'embroidery' || templateId === 'tailor') ? 'bg-pink-100 text-pink-700 dark:bg-pink-900/30 dark:text-pink-300 border border-pink-200 dark:border-pink-800' : 'bg-theme-surface dark:bg-theme-card text-theme-muted dark:text-theme-muted'}`}>
                              {item.workType}
                            </span>
                          )}
                        </div>
                        <span className="text-xs text-theme-primary dark:text-theme-primary dark:text-theme-secondary font-semibold">{val}</span>
                        {item.size && item.size !== 'N/A' && (
                          <span className={`block text-[10px] font-medium mt-0.5 ${(templateId === 'embroidery' || templateId === 'tailor') ? 'text-indigo-600 dark:text-indigo-400 font-bold bg-indigo-50 dark:bg-indigo-900/20 px-1.5 py-0.5 rounded-sm inline-block' : 'text-theme-muted dark:text-theme-muted'}`}>Size: {item.size}</span>
                        )}
                      </td>
                    );
                  }
                  
                  if (col.id === 'qty') {
                    return (
                      <td key={col.id} className={`py-4 text-${col.align} font-bold text-theme-muted dark:text-theme-muted`}>
                        {val}
                        {item.unit && <span className="text-[10px] ml-1 uppercase">{item.unit}</span>}
                      </td>
                    );
                  }
                  
                  if (col.id === 'amount' || col.id === 'rate' || col.id === 'discount' || col.id === 'tax') {
                    return (
                      <td key={col.id} className={`py-4 text-${col.align} ${col.id === 'amount' ? 'font-extrabold text-theme-primary dark:text-theme-primary dark:text-theme-primary' : col.id === 'discount' && val > 0 ? 'text-theme-danger dark:text-theme-danger font-semibold' : 'font-semibold text-theme-muted dark:text-theme-muted'}`}>
                        {col.id === 'discount' && val > 0 ? '-' : ''}{formatCurrency(val, currencySymbol, regionalPrefs.numberFormat)}
                      </td>
                    );
                  }
                  
                  return (
                    <td key={col.id} className={`py-4 text-${col.align} text-theme-muted dark:text-theme-muted font-medium`}>
                      {val}
                    </td>
                  );
                })}
              </tr>
            ))}
            {(!invoice.items || invoice.items.length === 0) && (
              <tr>
                <td colSpan="10" className="py-6 text-center text-theme-muted dark:text-theme-muted font-semibold">
                  No items listed on this invoice.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* 4. TOTALS SUM BLOCK */}
      <div className="flex flex-col sm:flex-row justify-between items-start gap-6 border-t border-theme-border-soft dark:border-theme-border-soft pt-6">
        {/* Invoice Notes */}
        <div className="flex-1 max-w-sm">
          {invoice.notes && (
            <>
              <span className="font-bold text-theme-muted dark:text-theme-muted uppercase tracking-wider block text-[10px] mb-1.5">{categoryWords.noteLabel}</span>
              <p className="text-xs text-theme-muted dark:text-theme-muted font-medium leading-relaxed bg-theme-app dark:bg-theme-surface/50 dark:bg-theme-app/20 rounded-2xl p-4 border border-theme-border-soft dark:border-theme-border-soft/50 dark:border-theme-border-soft/40 italic">
                "{invoice.notes}"
              </p>
            </>
          )}
        </div>

        {/* Math summary */}
        <div className="w-full sm:w-64 space-y-2 text-xs font-semibold text-theme-muted dark:text-theme-muted">
          <div className="flex justify-between">
            <span>Subtotal</span>
            <span className="text-theme-primary dark:text-theme-primary dark:text-theme-secondary font-bold">{formatCurrency(invoice.subtotal, currencySymbol, regionalPrefs.numberFormat)}</span>
          </div>
          {invoice.discountAmount > 0 && (
            <div className="flex justify-between text-theme-danger dark:text-rose-450 font-bold">
              <span>Discount</span>
              <span>-{formatCurrency(invoice.discountAmount, currencySymbol, regionalPrefs.numberFormat)}</span>
            </div>
          )}
          <div className="flex justify-between">
            <span>{regionalPrefs.taxLabel || 'Tax'} ({invoice.taxPercentage}%)</span>
            <span className="text-theme-primary dark:text-theme-primary dark:text-theme-secondary font-bold">{formatCurrency(invoice.taxAmount, currencySymbol, regionalPrefs.numberFormat)}</span>
          </div>
          
          <div className="flex justify-between items-center border-t border-theme-border-soft dark:border-theme-border-soft pt-3 text-theme-primary dark:text-theme-primary dark:text-theme-primary">
            <span className="text-sm font-extrabold text-theme-primary dark:text-theme-primary dark:text-theme-secondary">Grand Total</span>
            <span className="text-lg font-black text-theme-accent dark:text-theme-accent">
              {formatCurrency(invoice.grandTotal, currencySymbol, regionalPrefs.numberFormat)}
            </span>
          </div>
        </div>
      </div>

      {/* 4.5. PREMIUM PAYMENT QR CARD (CLIENT VIEW) */}
      {paymentPrefs?.paymentQrEnabled && paymentPrefs?.showQrInPreview && (
        (() => {
          const dueAmount = (invoice.balanceDue !== undefined && invoice.balanceDue !== null && invoice.balanceDue !== 0)
            ? invoice.balanceDue
            : invoice.grandTotal;
          const paymentMethod = paymentPrefs.paymentMethod || 'UPI';
          
          let qrText = '';
          if (paymentMethod === 'UPI') {
            const upiId = paymentPrefs.upiId || '';
            const payeeName = paymentPrefs.payeeName || businessPrefs.businessName || '';
            qrText = `upi://pay?pa=${upiId}&pn=${payeeName}&am=${dueAmount}&cu=${regionalPrefs.currencyCode || 'INR'}&tn=${invoice.invoiceNumber}`;
          } else if (paymentMethod === 'bKash') {
            const bkashNumber = paymentPrefs.bkashNumber || '';
            qrText = `bKash Payment\nMerchant/Personal Number: ${bkashNumber}\nAmount: ${dueAmount}\nInvoice: ${invoice.invoiceNumber}`;
          } else if (paymentMethod === 'Nagad') {
            const nagadNumber = paymentPrefs.nagadNumber || '';
            qrText = `Nagad Payment\nNumber: ${nagadNumber}\nAmount: ${dueAmount}\nInvoice: ${invoice.invoiceNumber}`;
          } else if (paymentMethod === 'Manual') {
            qrText = paymentPrefs.customPaymentLink || '';
          }

          if (!qrText) return null;

          return (
            <div className="mt-8 p-6 md:p-8 rounded-3xl bg-gradient-to-br from-theme-surface to-theme-card text-white shadow-xl relative overflow-hidden border border-theme-border-strong/50 dark:border-theme-border-soft/80">
              {/* Subtle background glow */}
              <div className="absolute -right-20 -bottom-20 w-60 h-60 bg-theme-accent/10 rounded-full blur-3xl pointer-events-none"></div>
              <div className="absolute -left-20 -top-20 w-60 h-60 bg-theme-accent-light rounded-full blur-3xl pointer-events-none"></div>

              <div className="flex flex-col md:flex-row items-center gap-6 relative z-10">
                {/* QR Code Frame */}
                <div className="p-3 bg-theme-card dark:bg-theme-card rounded-2xl shadow-lg border border-white/10 shrink-0 bg-white">
                  <DynamicQRCode value={qrText} size={128} />
                </div>

                {/* Info details */}
                <div className="flex-1 text-center md:text-left space-y-3 w-full">
                  <div className="space-y-1">
                    <span className="text-[10px] font-black uppercase tracking-wider text-theme-accent bg-theme-accent/10 px-2.5 py-1 rounded-full border border-theme-border-soft">
                      Scan to Pay with {paymentMethod}
                    </span>
                    <h4 className="text-xl font-extrabold tracking-tight mt-2 text-white">
                      {paymentPrefs.payeeName || businessPrefs.businessName || 'Business Payee'}
                    </h4>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-2 text-xs">
                    {paymentMethod === 'UPI' && paymentPrefs.upiId && (
                      <div className="text-theme-muted">
                        <span className="font-bold text-[9px] uppercase tracking-wider block text-theme-muted">UPI ID</span>
                        <span className="font-mono text-theme-primary font-semibold break-all">{paymentPrefs.upiId}</span>
                      </div>
                    )}
                    {paymentMethod === 'bKash' && paymentPrefs.bkashNumber && (
                      <div className="text-theme-muted">
                        <span className="font-bold text-[9px] uppercase tracking-wider block text-theme-muted">bKash Number</span>
                        <span className="font-mono text-theme-primary font-semibold break-all">{paymentPrefs.bkashNumber}</span>
                      </div>
                    )}
                    {paymentMethod === 'Nagad' && paymentPrefs.nagadNumber && (
                      <div className="text-theme-muted">
                        <span className="font-bold text-[9px] uppercase tracking-wider block text-theme-muted">Nagad Number</span>
                        <span className="font-mono text-theme-primary font-semibold break-all">{paymentPrefs.nagadNumber}</span>
                      </div>
                    )}
                    {paymentMethod === 'Manual' && paymentPrefs.customPaymentLink && (
                      <div className="text-theme-muted col-span-2">
                        <span className="font-bold text-[9px] uppercase tracking-wider block text-theme-muted">Payment Details / Link</span>
                        <span className="font-mono text-theme-primary font-semibold break-all truncate block max-w-md">{paymentPrefs.customPaymentLink}</span>
                      </div>
                    )}
                    
                    <div className="text-theme-muted">
                      <span className="font-bold text-[9px] uppercase tracking-wider block text-theme-muted">Due Amount</span>
                      <span className="font-extrabold text-sm text-theme-accent">
                        {formatCurrency(dueAmount, currencySymbol, regionalPrefs.numberFormat)}
                      </span>
                    </div>

                    <div className="text-theme-muted">
                      <span className="font-bold text-[9px] uppercase tracking-wider block text-theme-muted">Invoice Number</span>
                      <span className="font-semibold text-theme-primary">{invoice.invoiceNumber}</span>
                    </div>
                  </div>

                  {paymentPrefs.paymentNote && (
                    <div className="border-t border-white/10 pt-2.5 mt-1.5">
                      <p className="text-[10px] text-theme-muted italic">
                        Note: {paymentPrefs.paymentNote}
                      </p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          );
        })()
      )}

      {/* 4.5. PAYMENT PROOFS */}
      {invoice.paymentProofs && invoice.paymentProofs.length > 0 && (
        <div className="mt-8 border border-theme-border-soft rounded-2xl p-6 bg-theme-surface/50">
          <h4 className="text-xs font-bold uppercase tracking-wider text-theme-muted mb-4 flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-theme-accent" /> Payment Proofs
          </h4>
          <div className="flex flex-wrap gap-4">
            {invoice.paymentProofs.map((proof, i) => (
              <a key={i} href={proof.url} target="_blank" rel="noreferrer" className="relative w-24 h-24 rounded-xl border border-theme-border-soft overflow-hidden group shadow-sm hover:shadow-md transition-shadow block">
                <img src={proof.url} alt={`Payment Proof ${i + 1}`} className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-110" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                  <span className="text-white text-[10px] font-bold">View</span>
                </div>
              </a>
            ))}
          </div>
        </div>
      )}

      {/* 5. BRAND FOOTER SIGNATURE */}
      {templateId === 'professional' && (
        <div className="mt-8 flex justify-end">
          <div className="text-center w-48">
            <div className="h-16 border-b-2 border-theme-primary dark:border-theme-primary opacity-30 mb-2"></div>
            <span className="text-[10px] font-bold uppercase tracking-wider text-theme-primary dark:text-theme-primary">Authorized Signatory</span>
          </div>
        </div>
      )}
      {templateId === 'retail' && (
        <div className="mt-8 text-center text-lg font-black text-theme-primary dark:text-theme-primary italic opacity-50">
          Thank you for shopping with us!
        </div>
      )}
      {templateId === 'doctor' && (
        <div className="mt-8 p-4 bg-emerald-50 dark:bg-emerald-950/20 border-l-4 border-emerald-500 rounded text-[9px] text-emerald-800 dark:text-emerald-300 font-medium italic">
          Disclaimer: This document is for billing purposes only and does not constitute medical advice or a formal prescription unless explicitly signed by a registered practitioner.
        </div>
      )}
      <div className={`flex justify-center items-center gap-1.5 border-t pt-8 mt-8 text-[10px] text-theme-muted dark:text-theme-muted font-bold uppercase tracking-wider ${templateId === 'minimal' ? 'border-black' : 'border-theme-border-soft dark:border-theme-border-soft/80'}`}>
        <ShieldCheck className="w-4 h-4 text-theme-accent dark:text-theme-accent" />
        <span>Generated Securely via BillQyro Invoicing SaaS</span>
      </div>
    </div>
  );
};

export default InvoicePreview;

import React, { useState, useEffect } from 'react';
import Sidebar from './Sidebar';
import BottomNav from './BottomNav';
import { Search, Bell, Settings as SettingsIcon, Sparkles, ShieldCheck, User, Briefcase, Activity, HelpCircle, LogOut } from 'lucide-react';
import WorkspaceSwitcher from './WorkspaceSwitcher';
import Logo from './Logo';
import { settingsEngine } from '../services/settingsEngine';
import { flushSyncQueue } from '../services/syncEngine';
import AnimatedBorderTrail from './AnimatedBorderTrail';
import { AnimatedThemeToggler } from './AnimatedThemeToggler';
import { getNotifications, markNotificationAsRead, clearAllNotifications } from '../services/notificationsService';
import { useTheme } from '../contexts/ThemeContext';

const Layout = ({ children, currentTab, setCurrentTab, onLogout, businessSettings, isAuthenticated, userRole, invoices = [], subscription = {}, userEmail, onQuickBillOpen, pendingPaymentsCount = 0, businessWorkspaces, activeWorkspaceId, setActiveWorkspace, syncSource, syncStatus }) => {
  const { themeState } = useTheme();
  const isDarkMode = themeState.darkMode;

  const [isAccountMenuOpen, setIsAccountMenuOpen] = useState(false);
  const [isNotificationMenuOpen, setIsNotificationMenuOpen] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const searchInputRef = React.useRef(null);

  useEffect(() => {
    setNotifications(getNotifications());
    const handleNotifUpdate = () => setNotifications(getNotifications());
    window.addEventListener('billqyro_notifications_updated', handleNotifUpdate);
    return () => window.removeEventListener('billqyro_notifications_updated', handleNotifUpdate);
  }, []);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    setIsAccountMenuOpen(false);
    setIsNotificationMenuOpen(false);
  }, [currentTab]);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const toggleTheme = async () => {
    const newDarkMode = !isDarkMode;
    const currentSettings = await settingsEngine.getSettings() || {};
    currentSettings.darkMode = newDarkMode;
    if (currentSettings.themePreset === 'dark') {
      currentSettings.themePreset = 'light';
    }
    settingsEngine.saveSettings(currentSettings);
    
    // Broadcast setting update for ThemeContext
    window.dispatchEvent(new CustomEvent('billqyro:settings-updated', { detail: currentSettings }));
    window.dispatchEvent(new CustomEvent('billqyro_sync'));
  };

  const getPageTitle = (tab) => {
    switch (tab) {
      case 'dashboard':
        return 'Financial Dashboard';
      case 'invoices':
        return 'Invoices System';
      case 'create-invoice':
        return 'Invoice Builder';
      case 'estimates':
        return 'Estimates & Quotes';
      case 'pdf-templates':
        return 'PDF Templates';
      case 'live-link-templates':
      case 'billing-portal-settings':
      case 'student-portal-settings':
        return 'Live Link Studio';
      case 'marketplace':
        return 'Template Marketplace';
      case 'customers':
        return 'Client CRM';
      case 'patients':
        return 'Patient Records';
      case 'students':
        return 'Student Directory';
      case 'clients':
        return 'Client Roster';
      case 'products':
        return 'Product & Service Catalog';
      case 'expenses':
        return 'Overhead Expense Logger';
      case 'subscription':
        return 'Subscription Plan';
      case 'reports':
        return 'Reports & Analytics';
      case 'due-ledger':
        return 'Due Ledger';
      case 'pending-payments':
        return 'Payment Proofs';
      case 'backup-restore':
        return 'Backup & Restore';
      case 'help-center':
        return 'Help Center';
      case 'more':
        return 'More Workspace Options';
      case 'admin-panel':
        return 'Admin Control Panel';
      case 'settings':
        return 'Business Settings';
      default:
        return 'BillQyro';
    }
  };

  return (
    <div className="h-screen overflow-hidden bg-theme-app flex flex-col lg:flex-row w-full font-sans antialiased text-theme-primary transition-colors duration-300">
      <Sidebar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        onLogout={onLogout}
        businessSettings={businessSettings}
        isAuthenticated={isAuthenticated}
        userRole={userRole}
        userEmail={userEmail}
        pendingPaymentsCount={pendingPaymentsCount}
        businessWorkspaces={businessWorkspaces}
        activeWorkspaceId={activeWorkspaceId}
        setActiveWorkspace={setActiveWorkspace}
        syncStatus={syncStatus}
        flushSyncQueue={flushSyncQueue}
      />

      <div className="flex-1 flex flex-col min-w-0 w-full max-w-full pb-[calc(64px+env(safe-area-inset-bottom))] lg:pb-0 overflow-y-auto overflow-x-hidden bg-theme-app transition-colors duration-300 relative z-10">
        
        {localStorage.getItem('billqyro_demo_session_active') === 'true' && (
          <div className="bg-amber-500 text-amber-950 font-black text-xs py-1.5 text-center uppercase tracking-widest z-50 relative shadow-md flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-amber-900 animate-pulse"></span>
            DEMO MODE ACTIVE — Real data is safe
          </div>
        )}

        {businessSettings?.maintenanceMode && userRole !== 'admin' && userEmail !== 'khairul2052007@gmail.com' && (
          <div className="bg-rose-600 text-white font-black text-xs py-1.5 text-center uppercase tracking-widest z-50 relative shadow-md flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-white animate-pulse"></span>
            SYSTEM MAINTENANCE ACTIVE — Invoice creation, live links, and premium upgrades are temporarily disabled.
          </div>
        )}

        {/* ===== PREMIUM HEADER ===== */}
        {/* Desktop: Full featured header. Mobile: Compact 2-row (max-height 110px) */}
        <header className="sticky top-0 z-40 bg-theme-card/70 backdrop-blur-2xl border-b border-theme-accent/30 text-theme-primary shadow-premium-sm transition-all">
          <div className="absolute inset-0 overflow-hidden pointer-events-none">
            <div className="absolute top-0 right-0 w-64 h-64 bg-theme-surface dark:bg-theme-surface/5 rounded-full blur-3xl transform translate-x-20 -translate-y-20"></div>
            <div className="absolute -bottom-10 left-10 w-48 h-48 bg-theme-accent-light dark:bg-theme-accent-light rounded-full blur-2xl"></div>
          </div>

          {/* ===== DESKTOP HEADER (unchanged) ===== */}
          <div className="max-w-full w-full mx-auto px-4 lg:px-6 hidden md:flex flex-col md:flex-row md:items-center justify-between gap-4 relative z-10 py-4 md:py-5">
            
            <div className="flex items-start md:items-center gap-3">
              <div className="flex flex-col">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-[10px] uppercase font-bold tracking-widest text-theme-muted bg-theme-app px-2.5 py-0.5 rounded-full border border-theme-border-soft backdrop-blur-md">
                    Active Workspace
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <WorkspaceSwitcher
                    businessWorkspaces={businessWorkspaces}
                    activeWorkspaceId={activeWorkspaceId}
                    setActiveWorkspace={setActiveWorkspace}
                    setCurrentTab={setCurrentTab}
                  />
                  <span className="flex items-center gap-1 text-[9px] font-black uppercase tracking-wider text-theme-accent bg-theme-accent-light border border-theme-accent/15 px-2 py-0.5 rounded-full">
                    <ShieldCheck className="w-3 h-3" /> Secure
                  </span>
                  {localStorage.getItem('billqyro_demo_session_active') === 'true' ? (
                    <div className="relative group flex items-center gap-2">
                      <span className="flex items-center gap-1.5 text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full transition-colors text-amber-500 bg-amber-500/10 border border-amber-500/20">
                        <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse"></span> 
                        LOCAL SANDBOX
                      </span>
                      {userRole === 'admin' && (
                        <button 
                          onClick={() => {
                            localStorage.setItem('billqyro_demo_session_active', 'false');
                            window.location.reload();
                          }}
                          className="text-[9px] font-bold text-theme-muted hover:text-theme-primary underline uppercase tracking-wider"
                        >
                          Exit Sandbox
                        </button>
                      )}
                    </div>
                  ) : (
                    <div className="relative group flex items-center gap-2">
                      <span className={`flex items-center gap-1.5 text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full transition-colors ${
                        syncStatus === 'Synced' ? 'text-emerald-500 bg-emerald-500/10 border border-emerald-500/20' : 
                        syncStatus === 'Saving...' || syncStatus === 'Syncing...' ? 'text-blue-500 bg-blue-500/10 border border-blue-500/20 animate-pulse' : 
                        syncStatus === 'Offline' ? 'text-red-500 bg-red-500/10 border border-red-500/20' :
                        'text-amber-500 bg-amber-500/10 border border-amber-500/20'
                      }`}>
                        <span className={`w-1.5 h-1.5 rounded-full ${
                          syncStatus === 'Synced' ? 'bg-emerald-500' : 
                          syncStatus === 'Saving...' || syncStatus === 'Syncing...' ? 'bg-blue-500 animate-ping' : 
                          syncStatus === 'Offline' ? 'bg-red-500' :
                          'bg-amber-500'
                        }`}></span> 
                        {syncStatus === 'Synced' ? 'Cloud Synced' : syncStatus}
                      </span>
                      {(syncStatus === 'Pending Sync' || syncStatus === 'Sync Error') && (
                        <div className="absolute top-full left-0 mt-1 hidden group-hover:block z-50">
                          <button
                            onClick={flushSyncQueue}
                            className="text-[10px] font-bold uppercase tracking-wider bg-theme-card border border-theme-border-soft px-3 py-1.5 rounded shadow-lg text-theme-primary hover:bg-theme-accent hover:text-white transition-colors flex items-center gap-1 whitespace-nowrap"
                          >
                            <span className="w-1.5 h-1.5 rounded-full bg-amber-500"></span>
                            Retry Sync
                          </button>
                        </div>
                      )}
                      {userRole === 'admin' && (
                        <button 
                          onClick={() => {
                            localStorage.setItem('billqyro_demo_session_active', 'true');
                            window.location.reload();
                          }}
                          className="text-[9px] font-bold text-theme-muted hover:text-theme-primary underline uppercase tracking-wider hidden group-hover:block ml-1"
                        >
                          Enter Sandbox
                        </button>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="flex-1 max-w-xl hidden md:block px-4">
              <div className="relative group">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 text-theme-muted group-focus-within:text-theme-accent transition-colors" />
                </div>
                <input
                  ref={searchInputRef}
                  data-search-input
                  type="text"
                  placeholder="Search invoices, customers, products..."
                  className="block w-full pl-10 pr-14 py-2.5 bg-theme-surface border border-theme-accent/50 rounded-full text-sm font-semibold shadow-sm text-theme-primary placeholder-theme-secondary focus:bg-theme-card focus:outline-none focus:ring-2 focus:ring-theme-accent/50 focus:border-theme-accent transition-all duration-300 hover:shadow-md hover:border-theme-accent/70"
                />
                <div className="absolute inset-y-0 right-0 pr-2 flex items-center">
                  <span className="text-[10px] font-bold text-theme-muted bg-theme-surface px-1.5 py-0.5 rounded-md border border-theme-border-soft shadow-sm">
                    Ctrl K
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2 sm:gap-3 justify-end">
              <button title="Search" aria-label="Search" className="md:hidden w-11 h-11 rounded-2xl bg-theme-surface border border-theme-border-soft flex items-center justify-center text-theme-primary hover:bg-theme-app hover:shadow-md hover:border-theme-accent/30 active:scale-95 transition-all duration-300 shadow-sm relative group overflow-hidden">
                <AnimatedBorderTrail />
                <Search className="w-5 h-5 relative z-10" />
              </button>

              <div className="relative">
                <button 
                  onClick={() => setIsNotificationMenuOpen(!isNotificationMenuOpen)}
                  title="Notifications"
                  aria-label="Notifications"
                  className="w-11 h-11 md:w-[42px] md:h-[42px] rounded-2xl bg-theme-surface border border-theme-border-soft flex items-center justify-center text-theme-primary hover:bg-theme-app hover:shadow-md hover:border-theme-accent/30 active:scale-95 transition-all duration-300 shadow-sm relative group overflow-hidden"
                >
                  <AnimatedBorderTrail />
                  <Bell className="w-5 h-5 relative z-10" />
                  <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-theme-danger rounded-full border border-theme-app animate-pulse z-20"></span>
                </button>
                
                {isNotificationMenuOpen && (
                  <>
                    <div className="fixed inset-0 z-40" onClick={() => setIsNotificationMenuOpen(false)} />
                    <div className="absolute top-14 right-0 w-80 bg-theme-card rounded-2xl shadow-2xl border border-theme-border-soft z-50 overflow-hidden flex flex-col">
                      <div className="p-4 border-b border-theme-border-soft flex justify-between items-center bg-theme-surface/50">
                        <h3 className="text-sm font-bold text-theme-primary">Notifications</h3>
                        {notifications.filter(n => !n.read).length > 0 && (
                          <div className="flex gap-2 items-center">
                            <button onClick={clearAllNotifications} className="text-[10px] font-bold text-theme-muted hover:text-theme-primary underline">Clear All</button>
                            <span className="text-[10px] font-bold text-theme-accent bg-theme-accent-light px-2 py-0.5 rounded-full">{notifications.filter(n => !n.read).length} New</span>
                          </div>
                        )}
                      </div>
                      <div className="max-h-80 overflow-y-auto no-scrollbar p-2 space-y-1">
                        {notifications.length === 0 ? (
                          <p className="text-[10px] text-theme-muted text-center py-4 font-semibold">No new notifications</p>
                        ) : (
                          notifications.map((notif) => (
                            <div 
                              key={notif.id} 
                              onClick={() => markNotificationAsRead(notif.id)}
                              className={`p-3 hover:bg-theme-surface rounded-xl transition-colors cursor-pointer flex gap-3 ${notif.read ? 'opacity-60' : ''}`}
                            >
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${notif.type === 'success' ? 'bg-emerald-500/10 text-emerald-500' : notif.type === 'error' ? 'bg-rose-500/10 text-rose-500' : 'bg-theme-accent/10 text-theme-accent'}`}>
                                <Bell className="w-4 h-4" />
                              </div>
                              <div>
                                <p className="text-xs font-bold text-theme-primary">{notif.title}</p>
                                <p className="text-[10px] text-theme-muted mt-0.5">{notif.message}</p>
                              </div>
                            </div>
                          ))
                        )}
                      </div>
                    </div>
                  </>
                )}
              </div>

              <AnimatedThemeToggler
                className="w-11 h-11 md:w-[42px] md:h-[42px] rounded-2xl bg-theme-surface border border-theme-border-soft flex items-center justify-center text-theme-primary hover:bg-theme-app hover:shadow-md hover:border-theme-accent/30 active:scale-95 transition-all duration-300 shadow-sm relative group overflow-hidden"
                variant="circle"
                theme={isDarkMode ? "dark" : "light"}
                onThemeChange={(newTheme) => {
                  const newDarkMode = newTheme === "dark";
                  if (newDarkMode !== isDarkMode) {
                    toggleTheme();
                  }
                }}
                title={`Switch to ${!isDarkMode ? 'Dark' : 'Light'} Mode`}
              >
                <AnimatedBorderTrail />
              </AnimatedThemeToggler>

