 */
const Logo = ({ type = 'horizontal', className = '', forceWhiteText = false }) => {
  // Brand color gradients & assets definitions
  const defs = (
    <defs>
      {/* Light highlights for paper fold */}
      <linearGradient id="foldGradient" x1="0" y1="1" x2="1" y2="0">
