          {businessSettings?.address || ''}  |  {businessSettings?.phone || ''}
        </Text>
        <Text style={styles.compactTitle}>{getInvoiceTitle(invoice.billType)}</Text>
        <Text style={{ fontSize: 9, color: '#475569', marginTop: 4 }}>
