  { id: 'new-bill', label: 'New Bill', icon: Plus, color: 'bg-theme-accent', action: 'onQuickBillOpen' },
  { id: 'invoices', label: 'View Bills', icon: FileText, color: 'bg-blue-500', action: 'invoices' },
  { id: 'customers', label: 'Customers', icon: Users, color: 'bg-emerald-500', action: 'customers' },
  { id: 'collect', label: 'Collect Due', icon: CreditCard, color: 'bg-amber-500', action: 'due-ledger' },
];

const QuickActions = ({ actions = defaultActions, onAction, setCurrentTab }) => {
  const handleClick = (action) => {
    if (action.action?.startsWith('on')) {
      if (onAction) onAction(action.action);
    } else if (action.action) {
      if (setCurrentTab) setCurrentTab(action.action);
    }
  };

  return (
    <div className="card-premium p-5">
      <div className="section-header">
        <h3 className="section-header-title">Quick Actions</h3>
      </div>
      <motion.div
        variants={staggerContainer}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-2 sm:grid-cols-4 gap-2"
      >
        {actions.map((action) => {
          const Icon = action.icon;
          return (
            <motion.button
              key={action.id}
              variants={staggerItem}
              whileHover={{ y: -1, scale: 1.01 }}
              whileTap={{ scale: 0.97 }}
              onClick={() => handleClick(action)}
              className="flex flex-col items-center gap-2 p-4 rounded-xl bg-theme-surface hover:bg-theme-accent/10 transition-all duration-200 group border border-theme-border-soft hover:border-theme-accent/20"
            >
              <div className={`w-10 h-10 rounded-xl ${action.color} text-white flex items-center justify-center shadow-sm group-hover:shadow-md transition-all duration-200`}>
                <Icon className="w-5 h-5" />
              </div>
              <span className="text-2xs font-bold text-theme-primary text-center">{action.label}</span>
            </motion.button>
          );
        })}
      </motion.div>
    </div>
  );
};

export default QuickActions;

import React, { useState } from 'react';
import BottomSheet from './BottomSheet';
import { generateNextInvoiceNumber } from '../utils/invoiceUtils';
import { Download, Save } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { getCustomerLabelByType } from '../config/businessPresets';

const QuickBillModal = ({ isOpen, onClose, onSave, businessSettings, invoices }) => {
  const wsType = businessSettings?.businessWorkspaces?.find(ws => ws.id === businessSettings.activeWorkspaceId)?.type || businessSettings?.businessType || 'retail';
  const customerLabel = getCustomerLabelByType(wsType);
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [itemService, setItemService] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [rate, setRate] = useState('');
  const [paidAmount, setPaidAmount] = useState('');
  const [notes, setNotes] = useState('');

  const handleSave = (downloadPdf = false) => {
    if (!customerName || !itemService || !rate) {
      toast.error('Customer name, item, and rate are required.');
      return;
    }

    const qty = parseFloat(quantity) || 1;
    const itemRate = parseFloat(rate) || 0;
    const amount = qty * itemRate;
    const paid = parseFloat(paidAmount) || 0;
    const balanceDue = amount - paid;
    const paymentStatus = paid >= amount ? 'Paid' : (paid > 0 ? 'Partially Paid' : 'Pending');

    const today = new Date().toISOString().split('T')[0];

    // Construct the payload as expected by saveInvoice
    const payload = {
      id: 'inv-' + Date.now(),
      invoiceNumber: generateNextInvoiceNumber(invoices),
      date: today,
      dueDate: today,
      billType: businessSettings?.defaultBillingTemplate || 'custom',
      customerId: null, // Will create new customer if doesn't exist
      customerName,
      customerPhone,
      items: [{
        sn: 1,
        itemService: itemService,
        description: itemService, // generic fallback
        qty,
        rate: itemRate,
        amount
      }],
      taxPercentage: 0,
      discountAmount: 0,
      amountPaid: paid,
      balanceDue,
      notes,
      paymentStatus,
      orderStatus: 'Pending',
      subtotal: amount,
      taxAmount: 0,
      grandTotal: amount,
    };

    // Call the global save function
    onSave(payload, true); // true = save as new customer
    toast.success('Quick Bill Saved!');

    if (downloadPdf) {
      // PDF download will be triggered in App.js or we dispatch an event
      window.dispatchEvent(new CustomEvent('download-quick-bill-pdf', { detail: payload }));
    }

    // Reset form
    setCustomerName('');
    setCustomerPhone('');
    setItemService('');
    setQuantity(1);
    setRate('');
    setPaidAmount('');
    setNotes('');

    onClose();
  };

  return (
    <BottomSheet isOpen={isOpen} onClose={onClose} title="⚡ Quick Bill">
      <div className="space-y-4">
        {/* Customer Section */}
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-bold text-theme-muted mb-1">{customerLabel} Name *</label>
            <input
              type="text"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              className="w-full px-3 py-2 bg-theme-app dark:bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-semibold text-theme-primary dark:text-theme-primary"
              placeholder="Name"
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-theme-muted mb-1">Phone (Optional)</label>
            <input
              type="tel"
              value={customerPhone}
              onChange={(e) => setCustomerPhone(e.target.value)}
              className="w-full px-3 py-2 bg-theme-app dark:bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-semibold text-theme-primary dark:text-theme-primary"
              placeholder="Phone"
            />
          </div>
        </div>

        {/* Item Section */}
        <div>
          <label className="block text-xs font-bold text-theme-muted mb-1">Item / Service Name *</label>
          <input
            type="text"
            value={itemService}
            onChange={(e) => setItemService(e.target.value)}
            className="w-full px-3 py-2 bg-theme-app dark:bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-semibold text-theme-primary dark:text-theme-primary"
            placeholder="What are you selling?"
          />
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-bold text-theme-muted mb-1">Quantity</label>
            <input
              type="number"
              value={quantity}
              onChange={(e) => setQuantity(e.target.value)}
              className="w-full px-3 py-2 bg-theme-app dark:bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-semibold text-theme-primary dark:text-theme-primary"
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-theme-muted mb-1">Rate *</label>
            <div className="relative">
              <span className="absolute left-3 top-2 text-theme-muted font-bold">{businessSettings?.currency || '₹'}</span>
              <input
                type="number"
                value={rate}
                onChange={(e) => setRate(e.target.value)}
                className="w-full pl-8 pr-3 py-2 bg-theme-app dark:bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-semibold text-theme-primary dark:text-theme-primary"
                placeholder="0.00"
              />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-bold text-theme-muted mb-1">Total Amount</label>
            <div className="w-full px-3 py-2 bg-theme-surface dark:bg-theme-card border border-theme-border-soft rounded-lg text-sm font-bold text-theme-primary dark:text-theme-primary">
              {businessSettings?.currency || '₹'} {((parseFloat(quantity) || 1) * (parseFloat(rate) || 0)).toFixed(2)}
            </div>
          </div>
          <div>
            <label className="block text-xs font-bold text-theme-muted mb-1">Amount Paid</label>
            <div className="relative">
              <span className="absolute left-3 top-2 text-theme-muted font-bold">{businessSettings?.currency || '₹'}</span>
              <input
                type="number"
                value={paidAmount}
                onChange={(e) => setPaidAmount(e.target.value)}
                className="w-full pl-8 pr-3 py-2 bg-theme-app dark:bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-semibold text-theme-accent"
                placeholder="Optional"
              />
            </div>
          </div>
        </div>

        <div>
          <label className="block text-xs font-bold text-theme-muted mb-1">Notes (Optional)</label>
          <input
            type="text"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            className="w-full px-3 py-2 bg-theme-app dark:bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-semibold text-theme-primary dark:text-theme-primary"
            placeholder="Add a note..."
          />
        </div>

        {/* Action Buttons */}
        <div className="pt-4 grid grid-cols-2 gap-3">
          <button
            onClick={() => handleSave(false)}
            className="w-full py-3 bg-theme-surface dark:bg-theme-card text-theme-primary dark:text-theme-muted font-bold rounded-xl flex items-center justify-center gap-2"
          >
            <Save className="w-4 h-4" /> Save Only
          </button>
          <button
            onClick={() => handleSave(true)}
            className="w-full py-3 bg-theme-accent text-white font-bold rounded-xl flex items-center justify-center gap-2"
          >
            <Download className="w-4 h-4" /> Save & PDF
          </button>
        </div>
      </div>
    </BottomSheet>
  );
};

export default QuickBillModal;

import React from 'react';
import {
    CheckCircle2,
    Circle,
    Building2,
    Users,
    FileText,
    FileDown,
    HardDrive,
    Activity,
    Sparkles,
} from 'lucide-react';

/**
 * Setup Progress Tracker — shows how far along the user is in configuring BillQyro
 * @param {Object}  businessSettings - current business profile settings
 * @param {Array}   customers        - list of saved customers
 * @param {Array}   invoices         - list of created invoices
 */
const SetupProgress = ({ businessSettings = {}, customers = [], invoices = [] }) => {
    // Check each milestone
    const profileComplete = !!businessSettings.businessName;
    const customerAdded = customers.length > 0;
    const firstBillCreated = invoices.length > 0;

    const items = [
        {
            id: 'profile',
            label: 'Business Profile',
            icon: Building2,
            complete: profileComplete,
            detail: profileComplete ? 'Complete' : 'Incomplete',
        },
        {
            id: 'customer',
            label: 'Customer Added',
            icon: Users,
            complete: customerAdded,
            detail: customerAdded ? 'Complete' : 'Incomplete',
        },
        {
            id: 'bill',
            label: 'First Bill Created',
            icon: FileText,
            complete: firstBillCreated,
            detail: firstBillCreated ? 'Complete' : 'Incomplete',
        },
        {
            id: 'pdf',
            label: 'PDF Download',
            icon: FileDown,
            complete: true,
            detail: 'Ready',
        },
        {
            id: 'backup',
            label: 'Firebase / Local Backup',
            icon: HardDrive,
            complete: true,
            detail: 'Active',
        },
    ];

    const completedCount = items.filter((it) => it.complete).length;
    const progressPercent = Math.round((completedCount / items.length) * 100);

    return (
        <div className="bg-theme-card dark:bg-theme-card rounded-3xl p-5 md:p-6 border border-theme-border-soft dark:border-theme-border-soft/80 shadow-premium space-y-5">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                    <div className="p-1.5 rounded-xl bg-[image:var(--accent-gradient)] text-theme-button-text border-0 shadow-sm">
                        <Activity className="w-4 h-4" />
                    </div>
                    <div>
                        <h3 className="font-extrabold text-sm text-theme-primary dark:text-theme-primary dark:text-theme-secondary tracking-tight flex items-center gap-2">
                            <span>Setup Progress</span>
                            {progressPercent === 100 && (
                                <Sparkles className="w-4 h-4 text-theme-accent" />
                            )}
                        </h3>
                        <p className="text-[10px] text-theme-muted font-bold uppercase tracking-wider">
                            {progressPercent}% Complete
                        </p>
                    </div>
                </div>

                {/* Percentage Circle */}
                <div className="relative w-16 h-16 shrink-0">
                    <svg className="w-full h-full -rotate-90" viewBox="0 0 40 40">
                        {/* Background circle */}
                        <circle
                            cx="20"
                            cy="20"
                            r="16"
                            fill="none"
                            stroke="currentColor"
                            className="text-theme-primary dark:text-theme-primary dark:text-theme-primary"
                            strokeWidth="3"
                        />
                        {/* Progress arc */}
                        <circle
                            cx="20"
                            cy="20"
                            r="16"
                            fill="none"
                            stroke="url(#progressGradient)"
                            strokeWidth="3"
                            strokeLinecap="round"
                            strokeDasharray={`${(progressPercent / 100) * 100.53} 100.53`}
                        />
                        <defs>
                            <linearGradient id="progressGradient" x1="0" y1="0" x2="1" y2="1">
                                <stop offset="0%" stopColor="var(--accent)" />
                                <stop offset="100%" stopColor="var(--accent-dark)" />
                            </linearGradient>
                        </defs>
                    </svg>
                    <span className="absolute inset-0 flex items-center justify-center text-xs font-black text-theme-primary dark:text-theme-muted">
                        {progressPercent}%
                    </span>
                </div>
            </div>

            {/* Progress Bar */}
            <div className="w-full bg-theme-surface dark:bg-theme-card h-2.5 rounded-full overflow-hidden">
                <div
                    className="bg-[image:var(--accent-gradient)] h-full rounded-full transition-all duration-700 ease-out"
                    style={{ width: `${progressPercent}%` }}
                ></div>
            </div>

            {/* Milestone List */}
            <div className="space-y-2.5">
                {items.map((item) => {
                    const IconComp = item.icon;
                    return (
                        <div
                            key={item.id}
                            className="flex items-center justify-between p-2.5 rounded-2xl bg-theme-app dark:bg-theme-surface/50 dark:bg-theme-app/40 border border-theme-border-soft dark:border-theme-border-soft/50 dark:border-theme-border-soft/50 transition-all"
                        >
                            <div className="flex items-center gap-2.5">
                                {/* Status icon */}
                                <div
                                    className={`p-1.5 rounded-xl ${item.complete
                                            ? 'bg-theme-accent-light dark:bg-theme-accent-light/30 text-theme-accent'
                                            : 'bg-theme-surface dark:bg-theme-card text-theme-muted'
                                        }`}
                                >
                                    <IconComp className="w-3.5 h-3.5" />
                                </div>
                                <span className="text-xs font-bold text-theme-primary dark:text-theme-muted">
                                    {item.label}
                                </span>
                            </div>

                            {/* Status badge */}
                            <span
                                className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[9px] font-black uppercase ${item.complete
                                        ? 'bg-theme-accent-light border border-theme-border-soft text-theme-accent'
                                        : 'bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft text-theme-muted'
                                    }`}
                            >
                                {item.complete ? (
                                    <CheckCircle2 className="w-2.5 h-2.5" />
                                ) : (
                                    <Circle className="w-2.5 h-2.5" />
                                )}
                                <span>{item.detail}</span>
                            </span>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default SetupProgress;

import React from 'react';

const ShineBorder = ({
  children,
  className = '',
  borderWidth = 3,
  duration = 4,
}) => {
  return (
    <div
      className={`relative rounded-3xl ${className}`}
      style={{ padding: borderWidth }}
    >
      {/* Animated Gradient Layer */}
      <div className="absolute inset-0 rounded-3xl overflow-hidden pointer-events-none">
        <div
          className="absolute top-[-50%] left-[-50%] w-[200%] h-[200%] animate-spin opacity-100"
          style={{ 
            animationDuration: `${duration}s`,
            backgroundImage: `conic-gradient(from 0deg, transparent 0%, var(--accent) 30%, #f43f5e 50%, #0ea5e9 70%, transparent 100%)`
          }}
        />
      </div>

      {/* Content Layer */}
      <div className="relative rounded-[calc(1.5rem-2px)] h-full bg-theme-card">
        {children}
      </div>
    </div>
  );
};

export default ShineBorder;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LayoutDashboard, FileSpreadsheet, Users, Layers, LogOut, TrendingDown, Sparkles, HelpCircle, Settings as SettingsIcon, Bell, BookOpen, PieChart, Palette, Smartphone, Store, Database, ChevronsLeft, ChevronsRight, Scissors, Wrench, Briefcase, ShieldCheck, ShoppingBag, Calendar, Truck, FileText, Globe } from 'lucide-react';
import { authEngine } from '../services/authEngine';
import { t } from '../utils/i18n';
import { triggerLightHaptic } from '../utils/feedback';
import { getCustomerLabelByType, getInvoiceLabelByType, getPortalLabelByType } from '../config/businessPresets';
import Logo from './Logo';
import WorkspaceSwitcher from './WorkspaceSwitcher';
import { isEducationBusiness } from '../config/businessPresets';

/**
 * Premium Collapsible Desktop Sidebar Navigation
 * - Expanded: 240px with full text, logo, user card
 * - Collapsed: 72px with icons only + tooltips
 * - Persists collapsed state via localStorage
 */
const Sidebar = ({ 
  currentTab, setCurrentTab, onLogout, businessSettings, isAuthenticated, userEmail, pendingPaymentsCount = 0,
  businessWorkspaces, activeWorkspaceId, setActiveWorkspace, syncStatus, flushSyncQueue 
}) => {
  // Determine active workspace and its enabled modules
  const activeWsId = businessSettings?.activeWorkspaceId;
  const activeWorkspace = businessSettings?.businessWorkspaces?.find(ws => ws.id === activeWsId) || {};
  const enabledModules = activeWorkspace.enabledModules || [];

  const [isCollapsed, setIsCollapsed] = useState(() => {
    try {
      return localStorage.getItem('billqyro_sidebar_collapsed') === 'true';
    } catch {
      return false;
    }
  });
  
  const [isMounted, setIsMounted] = useState(false);
  useEffect(() => {
    setIsMounted(true);
  }, []);

  const handleLogout = () => {
    authEngine.logout();
    window.location.reload();
  };

  const toggleCollapsed = () => {
    setIsCollapsed(prev => {
      const next = !prev;
      try { localStorage.setItem('billqyro_sidebar_collapsed', String(next)); } catch {}
      return next;
    });
  };

  const wsType = businessSettings?.businessType || activeWorkspace.type || 'retail';

  const getCustomerLabel = () => getCustomerLabelByType(wsType);

  const getInvoiceLabel = () => getInvoiceLabelByType(wsType);

  let menuItems = [
    { id: 'dashboard', label: "Today's Business", icon: LayoutDashboard },

    { type: 'label', label: 'Billing' },
    { id: 'invoices', label: getInvoiceLabel(), icon: FileSpreadsheet, module: 'billing' },
    { id: 'estimates', label: 'Estimates & Quotes', icon: FileSpreadsheet },

    { type: 'label', label: 'Customers' },
    { id: 'customers', label: getCustomerLabel(), icon: Users, module: 'customers' },
    { id: 'patients', label: 'Patient Records', icon: Users, module: 'patients' },
    { id: 'students', label: 'Student Directory', icon: Users, module: 'students' },
    { id: 'clients', label: 'Client Roster', icon: Users, module: 'clients' },

    { type: 'label', label: 'Collections' },
    { id: 'due-ledger', label: 'Due Ledger', icon: BookOpen, module: 'dueLedger' },
    { id: 'pending-payments', label: 'Payment Proofs', icon: Bell, module: 'paymentProofs' },

    { type: 'label', label: 'Analytics' },
    { id: 'reports', label: 'Reports', icon: PieChart, module: 'reports' },
    { id: 'expenses', label: t('expenses'), icon: TrendingDown, module: 'expenses' },

    { type: 'label', label: 'Operations' },
    { id: 'products', label: t('products'), icon: Layers, module: 'products' },
    { id: 'orders', label: 'Orders', icon: ShoppingBag, module: 'orders' },
    { id: 'appointments', label: 'Appointments', icon: Calendar, module: 'appointments' },
    { id: 'delivery', label: 'Delivery Tracking', icon: Truck, module: 'delivery' },
    { id: 'measurements', label: 'Measurements', icon: Scissors, module: 'measurements' },
    { id: 'designBook', label: 'Design Book', icon: BookOpen, module: 'designBook' },
    { id: 'devices', label: 'Device Management', icon: Wrench, module: 'devices' },
    { id: 'serviceJobs', label: 'Service Jobs', icon: Wrench, module: 'serviceJobs' },
    { id: 'projects', label: 'Projects', icon: Briefcase, module: 'projects' },

    { type: 'label', label: 'Portals' },
    { id: 'customer-portal-config', label: getPortalLabelByType(wsType), icon: Globe },

    { type: 'label', label: 'System' },
    { id: 'settings', label: 'Settings Studio', icon: SettingsIcon },
    ...(localStorage.getItem('billqyro_demo_session_active') === 'true' ? [{ id: 'sandbox-admin', label: 'Sandbox Control Center', icon: ShieldCheck, module: 'sandbox' }] : []),
    { id: 'help-center', label: 'Help Center', icon: HelpCircle },
  ];

  if (wsType === 'cybercafe' || wsType === 'cyber_cafe') {
    menuItems = [
      { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
      { type: 'label', label: 'Services' },
      { id: 'portal-hub', label: 'Portal Hub', icon: Globe },
      { id: 'quick-tools', label: 'Quick Tools', icon: Sparkles },
      { type: 'label', label: 'Management' },
      { id: 'customer-register', label: 'Customer Register', icon: Users },
      { id: 'cash-management', label: 'Cash Management', icon: Briefcase },
      { type: 'label', label: 'System' },
      { id: 'settings', label: 'Settings Studio', icon: SettingsIcon },
      ...(localStorage.getItem('billqyro_demo_session_active') === 'true' ? [{ id: 'sandbox-admin', label: 'Sandbox Control Center', icon: ShieldCheck, module: 'sandbox' }] : []),
      { id: 'help-center', label: 'Help Center', icon: HelpCircle },
    ];
  }

  // Filter items based on enabledModules (if any)
  if (enabledModules.length) {
    menuItems = menuItems.filter(item => {
      // If the item has a 'module' property, check if it's enabled
      if (item.module && !enabledModules.includes(item.module)) {
        // Special case: if wsType is 'billing_only' and module is 'customers', we still show it because it's recommended
        if (wsType === 'billing_only' && item.module === 'customers') return true;
        // Always show sandbox module
        if (item.module === 'sandbox') return true;
        return false;
      }
      return true;
    });
  }

  return (
    <aside
      className="hidden lg:flex flex-col h-full z-30 overflow-hidden shrink-0 border-r border-theme-accent/50 bg-theme-sidebar/80 backdrop-blur-xl shadow-[4px_0_24px_-6px_rgba(0,0,0,0.08)]"
      style={{
        width: isCollapsed ? 72 : 240,
        minWidth: isCollapsed ? 72 : 240,
        transition: isMounted ? 'width 200ms cubic-bezier(0.25,0.1,0.25,1), min-width 200ms cubic-bezier(0.25,0.1,0.25,1)' : 'none',
      }}
    >
      {/* Brand Header */}
      <div className="shrink-0 border-b border-theme-accent/50 flex items-center justify-between overflow-hidden"
        style={{ padding: isCollapsed ? '16px 12px' : '20px 20px', transition: isMounted ? 'padding 200ms cubic-bezier(0.25,0.1,0.25,1)' : 'none' }}
      >
        {isCollapsed ? (
          <div className="w-full flex justify-center">
            <Logo type="icon" className="w-9 h-9" />
          </div>
        ) : (
          <Logo type="horizontal" forceWhiteText={false} />
        )}
      </div>

      {/* User Card & Collapse Toggle */}
      <div className={`shrink-0 border-b border-theme-accent/50 flex ${isCollapsed ? 'flex-col items-center py-2 gap-2' : 'flex-row items-center justify-between px-3 py-2'}`}>
        {/* User Card */}
