                <button
                  onClick={() => setShowPdfSettings(false)}
                  className="flex-1 py-2.5 bg-[image:var(--accent-gradient)] text-theme-button-text border-0 text-xs font-black rounded-xl shadow-md transition-all"
                >
                  Save & Close
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>


    </>
  );
};
