import React, { useState, useEffect, useRef } from 'react';
import { Search, Plus } from 'lucide-react';

const ProductSearch = ({ 
  value, 
  onChange, 
  onSelectProduct, 
  products = [], 
  placeholder = "Search or type new item...",
  className = ""
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [filtered, setFiltered] = useState([]);
  const wrapperRef = useRef(null);

  useEffect(() => {
    // Filter out invalid products first
    const validProducts = products.filter(p => p.name || p.productName);

    if (value) {
      const lower = value.toLowerCase();
      const matches = validProducts.filter(p => {
        const pName = (p.name || p.productName || '').toLowerCase();
        const pDesc = (p.description || '').toLowerCase();
        // Improve search accuracy (matches start of word or substring better)
        return pName.includes(lower) || pDesc.includes(lower);
      });
      setFiltered(matches);
    } else {
      setFiltered(validProducts.slice(0, 5)); // Show top 5 when empty
    }
  }, [value, products]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div className="relative w-full" ref={wrapperRef}>
      <div className="relative">
        <input
          type="text"
          value={value}
          onChange={(e) => {
            onChange(e.target.value);
            setIsOpen(true);
          }}
          onFocus={() => setIsOpen(true)}
          placeholder={placeholder}
          className={`w-full px-4 py-2.5 bg-theme-card border border-theme-border-soft rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary transition-all ${className}`}
        />
        {/* We don't add an icon here to match other inputs, but we could add a subtle search icon */}
      </div>

      {isOpen && (
        <div className="absolute z-[100] w-full mt-1 bg-theme-card border border-theme-border-soft rounded-xl shadow-xl max-h-60 overflow-y-auto overflow-x-hidden">
          {filtered.length > 0 ? (
            filtered.map((product, idx) => (
              <button
                key={product.id || product.productId || `prod-${idx}`}
                type="button"
                onClick={() => {
                  onSelectProduct(product);
                  setIsOpen(false);
                }}
                className="w-full text-left px-4 py-3 border-b border-theme-border-soft last:border-0 hover:bg-theme-surface transition-colors flex flex-col gap-1"
              >
                <div className="flex justify-between items-center">
                  <span className="font-bold text-theme-primary text-sm">{product.name || product.productName}</span>
                  <span className="font-mono text-xs text-theme-accent font-bold">
                    {(product.price > 0 || product.rate > 0) ? `₹${product.price || product.rate}` : ''}
                  </span>
                </div>
                {product.description && (
                  <span className="text-[10px] text-theme-muted line-clamp-1">{product.description}</span>
                )}
              </button>
            ))
          ) : (
            <div className="px-4 py-4 text-center">
              <span className="text-xs font-bold text-theme-muted">No products found</span>
              {value && <span className="block text-[10px] text-theme-muted/70 mt-1">Press enter to add as new item</span>}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ProductSearch;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Plus, Trash2, Save, Check } from 'lucide-react';
import { useInvoice } from '../../../contexts/InvoiceContext';
import ProductSearch from '../ProductSearch';
import { getCustomerLabelByType } from '../../../config/businessPresets';

const QuickBillForm = ({ customers, products, onSaveInvoice }) => {
  const { state, dispatch, businessSettings } = useInvoice();
  const wsType = businessSettings?.businessWorkspaces?.find(ws => ws.id === businessSettings.activeWorkspaceId)?.type || businessSettings?.businessType || 'retail';
  const customerLabel = getCustomerLabelByType(wsType);
  const currencySymbol = businessSettings?.currency || '₹';

  // Customer selection
  const handleCustomerSelect = (e) => {
    const custId = e.target.value;
    if (custId) {
      const cust = customers.find(c => c.id === custId);
      if (cust) {
        dispatch({ type: 'SET_CUSTOMER', payload: { id: cust.id, name: cust.name, phone: cust.phone || '', address: cust.address || '', email: cust.email || '' } });
      }
    } else {
      dispatch({ type: 'SET_CUSTOMER', payload: { id: '', name: '', phone: '', address: '', email: '' } });
    }
  };

  const handleCustomerNameChange = (e) => {
    dispatch({ type: 'SET_CUSTOMER', payload: { ...state.customer, name: e.target.value, id: '' } });
  };

  const handleCustomerPhoneChange = (e) => {
    dispatch({ type: 'SET_CUSTOMER', payload: { ...state.customer, phone: e.target.value } });
  };

  // Items
  const handleItemChange = (index, fieldOrUpdates, optionalValue) => {
    const newItems = [...state.items];

    if (typeof fieldOrUpdates === 'string') {
        const field = fieldOrUpdates;
        const isNumField = ['rate', 'price', 'mrp', 'qty', 'amount'].includes(field);
        newItems[index][field] = isNumField ? (optionalValue === '' ? '' : (parseFloat(optionalValue) || 0)) : optionalValue;
    } else {
        Object.entries(fieldOrUpdates).forEach(([field, val]) => {
            const isNumField = ['rate', 'price', 'mrp', 'qty', 'amount'].includes(field);
            newItems[index][field] = isNumField ? (val === '' ? '' : (parseFloat(val) || 0)) : val;
        });
    }

    // Auto calculate amount
    const qty = parseFloat(newItems[index].qty) || 1;
    const rate = parseFloat(newItems[index].rate || newItems[index].price || 0);
    newItems[index].amount = qty * rate;

    dispatch({ type: 'SET_ITEMS', payload: newItems });
  };

  const handleAddItem = () => {
    const generateId = () => {
      try {
        return crypto.randomUUID();
      } catch (e) {
        return `item-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      }
    };
    dispatch({ type: 'SET_ITEMS', payload: [...state.items, { id: generateId(), item: '', rate: 0, qty: 1, amount: 0 }] });
  };

  const removeItem = (index) => {
    const newItems = state.items.filter((_, i) => i !== index);
    dispatch({ type: 'SET_ITEMS', payload: newItems });
  };

  const handleSave = (statusOverride) => {
    if (!state.customer.name) {
      toast.error("Please add a customer name");
      return;
    }

    const cleanedItems = state.items.filter(i => i.item || i.rate > 0).map(i => ({
      ...i,
      qty: parseFloat(i.qty) || 1,
      rate: parseFloat(i.rate) || 0,
      amount: (parseFloat(i.qty) || 1) * (parseFloat(i.rate) || 0)
    }));

    if (cleanedItems.length === 0) {
      toast.error("Please add at least one item");
      return;
    }

    const payload = {
      ...state,
      items: cleanedItems,
      customerId: state.customer.id || null,
      customerName: state.customer.name,
      customerPhone: state.customer.phone,
      paymentStatus: statusOverride === 'Draft' ? 'Draft' : state.settings.paymentStatus,
      paymentMethod: state.settings.paymentMethod || 'Cash',
      amountPaid: state.totals.amountPaid || 0,
      balanceDue: state.totals.balanceDue || state.totals.grandTotal,
      businessSnapshot: businessSettings,
      paymentSettingsSnapshot: businessSettings,
      regionalSettingsSnapshot: businessSettings
    };

