// Extracted pure function for row calculation
const calculateRowAmount = (item) => {
  const q = parseFloat(item.qty) || 0;
  const r = parseFloat(item.rate) || 0;
  const d = parseFloat(item.discount) || 0;
  return Math.max(0, (q * r) - d);
};

