import React, { createContext, useContext, useState } from 'react';
import { settingsEngine } from '../services/settingsEngine';

const OnboardingContext = createContext();

export const useOnboarding = () => {
  const context = useContext(OnboardingContext);
  if (!context) {
    throw new Error('useOnboarding must be used within an OnboardingProvider');
  }
  return context;
};

export const OnboardingProvider = ({ children }) => {
  const [onboardingStep, setOnboardingStep] = useState(2);
  const [onboardingData, setOnboardingData] = useState(() => {
    // Initialize with existing settings if available
    const existing = settingsEngine.getSettings() || {};
    return {
      country: existing.country || null,
      businessDetails: {
        businessName: existing.businessName || '',
        ownerName: existing.ownerName || '',
        phone: existing.phone || '',
        whatsapp: existing.phone || '',
        address: existing.address || '',
        logoUrl: existing.logoUrl || '',
        experience: existing.experience || 'beginner'
      },
      paymentSetup: {
        paymentEnabled: existing.paymentQrEnabled !== false,
        paymentMethod: existing.paymentMethod || 'UPI',
        upiId: existing.upiId || '',
        bkashNumber: existing.bkashNumber || '',
        nagadNumber: existing.nagadNumber || '',
        bankAccountDetails: existing.customPaymentLink || ''
      },
      templateChoice: existing.defaultBillingTemplate || null,
      pharmacyEnabled: existing.pharmacyEnabled || false,
      tutorialCompleted: existing.tutorialCompleted || false,
    };
  });

  const updateData = (section, data) => {
    setOnboardingData(prev => ({
      ...prev,
      [section]: typeof data === 'object' ? { ...prev[section], ...data } : data
    }));
  };

  const nextStep = () => {
    setOnboardingStep(prev => prev + 1);
  };

  const prevStep = () => {
    setOnboardingStep(prev => Math.max(prev - 1, 1));
  };

  const skipToTutorial = () => {
    setOnboardingStep(7);
  };

  return (
    <OnboardingContext.Provider 
      value={{ 
        onboardingStep, 
        setOnboardingStep, 
        onboardingData, 
        updateData, 
        nextStep, 
        prevStep,
        skipToTutorial
      }}
    >
      {children}
    </OnboardingContext.Provider>
  );
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { applyTheme } from '../hooks/useThemeEngine';
import { settingsEngine } from '../services/settingsEngine';

const ThemeContext = createContext();

export const ThemeProvider = ({ children }) => {
  const [themeState, setThemeState] = useState({
    themeId: 'obsidian-gold',
    darkMode: false,
    brandColor: null,
    themeType: 'built-in'
  });

  useEffect(() => {
    // Initial load from settings
    const loadInitialTheme = async () => {
      const settings = await settingsEngine.getSettings();
      if (settings) {
        setThemeState({
          themeId: settings.themeColor || settings.themePreset || 'obsidian-gold',
          darkMode: settings.darkMode === true || settings.darkMode === 'true',
          brandColor: settings.brandColor || null,
          themeType: settings.themeType || 'built-in'
        });
      }
    };

    loadInitialTheme();

    // Listen for setting updates across the app
    const handleSettingsUpdate = (e) => {
      const settings = e.detail;
      setThemeState({
        themeId: settings.themeColor || settings.themePreset || 'obsidian-gold',
        darkMode: settings.darkMode === true || settings.darkMode === 'true',
        brandColor: settings.brandColor || null,
        themeType: settings.themeType || 'built-in'
      });
    };

    window.addEventListener('billqyro:settings-updated', handleSettingsUpdate);
    return () => window.removeEventListener('billqyro:settings-updated', handleSettingsUpdate);
  }, []);

  useEffect(() => {
    // Apply to DOM whenever state changes
    const effectiveThemeId = themeState.themeType === 'custom' && themeState.brandColor ? 'custom' : themeState.themeId;
    applyTheme(effectiveThemeId, themeState.brandColor, themeState.darkMode);
  }, [themeState]);

  return (
    <ThemeContext.Provider value={{ themeState, setThemeState }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => useContext(ThemeContext);

import { useState } from 'react';
import { pdf } from '@react-pdf/renderer';
import PdfDocument from '../components/PdfDocument';
import { toast } from 'react-hot-toast';
import QRCode from 'qrcode';

export const useGeneratePDF = () => {
  const [isGenerating, setIsGenerating] = useState(false);

  // Helper to fetch QR code image and convert to Base64
  const getQrBase64 = async (invoice, businessSettings) => {
    const paymentPrefs = invoice.paymentSettingsSnapshot || businessSettings;
    if (!paymentPrefs?.paymentQrEnabled || !paymentPrefs?.showQrInPreview) return null;

    const liveLink = `${window.location.origin}/invoice/${invoice.publicToken || invoice.id}`;
    try {
      return await QRCode.toDataURL(liveLink, { margin: 1, width: 150 });
    } catch (err) {
      console.error('QR Generate Error:', err);
      return null;
    }
  };

  const generatePDF = async (invoice, businessSettings, filename = null) => {
    setIsGenerating(true);

    try {
      // 1. Prepare dynamic assets like QR Code
      const qrCodeBase64 = await getQrBase64(invoice, businessSettings);

      // 2. Generate PDF Blob using @react-pdf/renderer
      const blob = await pdf(
        <PdfDocument 
          invoice={invoice} 
          businessSettings={businessSettings} 
          qrCodeBase64={qrCodeBase64} 
        />
      ).toBlob();

      // 3. Create Object URL and trigger download
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename || `Invoice_${invoice.invoiceNumber || 'Draft'}.pdf`;
      document.body.appendChild(link);
      link.click();

      // 4. Cleanup
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast.success('Vector PDF generated successfully!');
    } catch (error) {
      console.error('Error generating PDF:', error);
      toast.error('Failed to generate PDF. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  return { generatePDF, isGenerating };
};

export default useGeneratePDF;

import { useCallback } from 'react';

/**
 * usePremiumUX - Custom hook for providing Haptic Feedback and Audio sounds.
 * Helps create a native app-like experience on supported mobile devices.
 */
export const usePremiumUX = () => {

  // Play a soft "success" cash-register / ding sound
  const playSuccessSound = useCallback(() => {
    try {
      const settings = JSON.parse(localStorage.getItem('billqyro_settings') || '{}');
      if (settings.enableSounds === false) return;

      // Create a short satisfying beep using Web Audio API so we don't need external mp3s
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;

      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gainNode = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, ctx.currentTime); // High pitch
      osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1);

      gainNode.gain.setValueAtTime(0, ctx.currentTime);
      gainNode.gain.linearRampToValueAtTime(0.3, ctx.currentTime + 0.05);
      gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);

      osc.connect(gainNode);
      gainNode.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 0.3);
    } catch (e) {
      console.warn("Audio playback failed", e);
    }
  }, []);

  const vibrateSuccess = useCallback(() => {
    try {
      const settings = JSON.parse(localStorage.getItem('billqyro_settings') || '{}');
      if (settings.enableHaptics === false) return;

      if (typeof navigator !== 'undefined' && navigator.vibrate) {
        // Two quick, sharp vibrations
        navigator.vibrate([50, 50, 50]);
      }
    } catch (e) { /* ignore */ }
  }, []);

  const vibrateError = useCallback(() => {
    try {
      const settings = JSON.parse(localStorage.getItem('billqyro_settings') || '{}');
      if (settings.enableHaptics === false) return;

      if (typeof navigator !== 'undefined' && navigator.vibrate) {
        // One long, heavy vibration
        navigator.vibrate(200);
      }
    } catch (e) { /* ignore */ }
  }, []);

  const triggerSuccess = useCallback(() => {
    playSuccessSound();
    vibrateSuccess();
  }, [playSuccessSound, vibrateSuccess]);

  return {
    triggerSuccess,
    vibrateSuccess,
    vibrateError,
    playSuccessSound
  };
};

import { useEffect } from 'react';
import { updateFaviconForTheme } from '../utils/themeIcon';

const hexToRgb = (hex) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) } : null;
};

const shadeColor = (color, percent) => {
  let R = parseInt(color.substring(1, 3), 16);
  let G = parseInt(color.substring(3, 5), 16);
  let B = parseInt(color.substring(5, 7), 16);
  R = Math.min(255, parseInt(R * (100 + percent) / 100));
  G = Math.min(255, parseInt(G * (100 + percent) / 100));
  B = Math.min(255, parseInt(B * (100 + percent) / 100));
  const toHex = (n) => (n.toString(16).length === 1 ? '0' + n.toString(16) : n.toString(16));
  return '#' + toHex(R) + toHex(G) + toHex(B);
};

export const applyTheme = (themeId, brandColor = null, darkMode = false, persist = true) => {
  applyFullTheme({ themeColor: themeId, brandColor, darkMode }, persist);
};

export const applyFullTheme = (settings, persist = true) => {
  if (!settings) return;
  const root = document.documentElement;

  const { themeColor, brandColor, darkMode, cornerRadius, shadowIntensity, animationSpeed, fontDensity } = settings;
  const themeId = themeColor || 'obsidian-gold';

  if (darkMode) {
    root.classList.add('dark');
  } else {
    root.classList.remove('dark');
  }

  // Brand Color
  if (brandColor && themeId === 'custom') {
    const rgb = hexToRgb(brandColor);
    if (rgb) {
      root.removeAttribute('data-theme');
      root.style.setProperty('--accent', brandColor);
      root.style.setProperty('--accent-light', `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.15)`);
      root.style.setProperty('--border-soft', `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.15)`);
      root.style.setProperty('--border-strong', `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.3)`);
      root.style.setProperty('--accent-glow', `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.25)`);
      root.style.setProperty('--accent-gradient', `linear-gradient(135deg, ${brandColor}, ${shadeColor(brandColor, -20)})`);
      root.style.setProperty('--chart-primary', brandColor);
      root.style.setProperty('--sidebar-active', `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.1)`);
    }
  } else {
    root.style.removeProperty('--accent');
    root.style.removeProperty('--accent-light');
    root.style.removeProperty('--border-soft');
    root.style.removeProperty('--border-strong');
    root.style.removeProperty('--accent-glow');
    root.style.removeProperty('--accent-gradient');
    root.style.removeProperty('--chart-primary');
    root.style.removeProperty('--sidebar-active');
    root.setAttribute('data-theme', themeId);
  }

  // Modifiers
  if (cornerRadius !== undefined) root.style.setProperty('--radius-base', `${cornerRadius}px`);
  if (animationSpeed !== undefined) root.style.setProperty('--animation-multiplier', `${animationSpeed}s`);
  if (shadowIntensity !== undefined) root.style.setProperty('--shadow-opacity', `${shadowIntensity / 100}`);

  updateFaviconForTheme(themeId);

  if (persist) {
    localStorage.setItem('billqyro_theme_color', themeId);
    localStorage.setItem('billqyro_dark_mode', String(darkMode));
  }
};

export const useThemeEngine = (businessSettings) => {
  useEffect(() => {
    if (!businessSettings) return;

    applyFullTheme(businessSettings);
  }, [businessSettings?.themeColor, businessSettings?.brandColor, businessSettings?.themeType, businessSettings?.darkMode, businessSettings?.plan, businessSettings?.cornerRadius, businessSettings?.animationSpeed, businessSettings?.shadowIntensity]);
};

