  const target = new Date(dateStr);
  target.setHours(0, 0, 0, 0);
  const diff = Math.floor((target - today) / (1000 * 60 * 60 * 24));
  if (diff === 0) return 'Today';
  if (diff === 1) return 'Tomorrow';
  if (diff >= 2 && diff <= 6) return 'This Week';
  if (diff < 0) return 'Past';
  return 'Later';
};

const getNextId = () => 'apt-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5);

const formatDate = (dateStr) => {
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
};

const formatTime = (timeStr) => {
  if (!timeStr) return '';
  const [h, m] = timeStr.split(':');
  const hour = parseInt(h, 10);
  const ampm = hour >= 12 ? 'PM' : 'AM';
  const hour12 = hour % 12 || 12;
  return `${hour12}:${m} ${ampm}`;
};

const todayStr = () => new Date().toISOString().split('T')[0];

const Appointments = ({ invoices, customers = [], businessSettings, setCurrentTab }) => {
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);

  const [formData, setFormData] = useState({
    customerId: '',
    customerName: '',
    customerPhone: '',
    date: todayStr(),
    time: '10:00',
    serviceType: 'Consultation',
    status: 'Scheduled',
    notes: ''
  });

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      try {
        let stored = [];
        try {
          const raw = localStorage.getItem(STORAGE_KEY);
          if (raw) stored = JSON.parse(raw);
        } catch (e) { /* ignore */ }

        try {
          const { invoiceEngine } = await import('../services/invoiceEngine');
          if (typeof syncFromFirestore === 'function') {
            await syncFromFirestore();
          }
        } catch (e) { /* dbEngine functions not available */ }

        if (!cancelled) {
          setAppointments(Array.isArray(stored) ? stored : []);
        }
      } catch (e) {
        if (!cancelled) setAppointments([]);
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    load();
    return () => { cancelled = true; };
  }, []);

