import React, { useState } from 'react';
import AnimatedPage from '../components/AnimatedPage';
import { 
  Store, 
  Plus, 
  Edit3, 
  Archive, 
  CheckCircle2, 
  Circle,
  Settings2,
  ChevronRight,
  ArrowLeft
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { BUSINESS_PRESETS, ALL_MODULES as ALL_MODULES_CONFIG } from '../config/businessPresets';

const ALL_MODULES = ALL_MODULES_CONFIG;

const WorkspaceManager = ({ 
  businessWorkspaces, 
  activeWorkspaceId, 
  setActiveWorkspace,
  settings,
  onSaveSettings,
  setCurrentTab
}) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingWorkspace, setEditingWorkspace] = useState(null);

  // Form State
  const [name, setName] = useState('');
  const [type, setType] = useState('retail');
  const [enabledModules, setEnabledModules] = useState(['billing', 'customers']);

  const workspaces = businessWorkspaces || [];
  const activeCount = workspaces.filter(w => !w.archived).length;

  const handleOpenAdd = () => {
    setIsAdding(true);
    setEditingWorkspace(null);
    setName('');
    setType('retail');
    setEnabledModules(['billing', 'customers', 'products', 'dueLedger', 'reports']);
  };

  const handleOpenEdit = (ws) => {
    setIsAdding(true);
    setEditingWorkspace(ws);
    setName(ws.name || '');
    setType(ws.type || 'retail');
    setEnabledModules(ws.enabledModules || []);
  };

  const toggleModule = (modId) => {
    if (enabledModules.includes(modId)) {
      setEnabledModules(enabledModules.filter(id => id !== modId));
    } else {
      setEnabledModules([...enabledModules, modId]);
    }
  };

  const handleSave = () => {
    if (!name.trim()) return;

    let updatedWorkspaces = [...workspaces];

    if (editingWorkspace) {
      updatedWorkspaces = updatedWorkspaces.map(ws => {
        if (ws.id === editingWorkspace.id) {
          return { ...ws, name, type, enabledModules };
        }
        return ws;
      });
    } else {
      const newWs = {
        id: 'ws_' + Date.now(),
        name,
        type,
        enabledModules,
        archived: false
      };
      updatedWorkspaces.push(newWs);
      if (updatedWorkspaces.length === 1) {
        setActiveWorkspace(newWs.id);
      }
    }

    onSaveSettings({ ...settings, businessWorkspaces: updatedWorkspaces });
    setIsAdding(false);
  };

  const handleToggleArchive = (ws) => {
    if (ws.id === activeWorkspaceId) {
      alert("Cannot archive the currently active workspace.");
      return;
    }

    const updatedWorkspaces = workspaces.map(w => {
      if (w.id === ws.id) {
        return { ...w, archived: !w.archived };
      }
      return w;
    });
    onSaveSettings({ ...settings, businessWorkspaces: updatedWorkspaces });
  };

  return (
    <AnimatedPage>
      <div className="max-w-2xl mx-auto pb-24">
      {/* Header */}
      <div className="flex items-center gap-4 mb-6">
        <button 
          onClick={() => setCurrentTab('more')}
          className="w-10 h-10 bg-theme-card border border-theme-border-soft rounded-xl flex items-center justify-center text-theme-muted hover:text-theme-primary transition-colors"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-xl md:text-2xl font-black text-theme-primary tracking-tight">Workspace Manager</h1>
          <p className="text-xs font-bold text-theme-muted">{activeCount} Active Workspaces</p>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {!isAdding ? (
          <motion.div 
            key="list"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="space-y-4"
          >
            {/* Workspaces List */}
            {workspaces.map(ws => (
              <div 
                key={ws.id} 
                className={`bg-theme-card rounded-3xl p-5 border shadow-premium transition-all relative overflow-hidden ${ws.archived ? 'opacity-60 border-theme-border-soft' : ws.id === activeWorkspaceId ? 'border-theme-accent ring-1 ring-theme-accent/20' : 'border-theme-border-soft'}`}
              >
                {ws.id === activeWorkspaceId && (
                  <div className="absolute top-0 right-0 bg-theme-accent text-white text-[9px] font-black uppercase px-3 py-1 rounded-bl-xl tracking-wider">
                    Active
                  </div>
                )}

                <div className="flex items-center justify-between">
                  <div 
                    className="flex items-center gap-4 cursor-pointer flex-1"
                    onClick={() => {
                      if (!ws.archived) setActiveWorkspace(ws.id);
                    }}
                  >
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${ws.id === activeWorkspaceId ? 'bg-theme-accent text-white shadow-lg shadow-theme-accent/30' : 'bg-theme-app text-theme-muted'}`}>
                      <Store className="w-6 h-6" />
                    </div>
                    <div>
                      <h3 className="font-extrabold text-theme-primary">{ws.name}</h3>
                      <p className="text-[11px] font-bold text-theme-muted capitalize">{ws.type} • {ws.enabledModules?.length || 0} Modules</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => handleOpenEdit(ws)}
                      className="w-8 h-8 rounded-full bg-theme-app hover:bg-theme-surface flex items-center justify-center text-theme-muted transition-colors"
                    >
                      <Edit3 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => handleToggleArchive(ws)}
                      className={`w-8 h-8 rounded-full flex items-center justify-center transition-colors ${ws.archived ? 'bg-theme-success/10 text-theme-success hover:bg-theme-success/20' : 'bg-theme-danger/10 text-theme-danger hover:bg-theme-danger/20'}`}
                      title={ws.archived ? "Restore" : "Archive"}
                    >
                      <Archive className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}

            {/* Add Button */}
            <button
              onClick={handleOpenAdd}
              className="w-full mt-6 py-4 bg-[image:var(--accent-gradient)] text-white font-black rounded-2xl shadow-premium flex items-center justify-center gap-2 active:scale-[0.98] transition-transform"
            >
              <Plus className="w-5 h-5" /> Add New Workspace
            </button>
          </motion.div>
        ) : (
          <motion.div 
            key="form"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="space-y-6"
          >
            <div className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium space-y-5">
              <div>
                <label className="block text-xs font-black text-theme-muted uppercase tracking-wider mb-2">Workspace Name</label>
                <input 
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="e.g. Branch 2"
                  className="w-full bg-theme-app border border-theme-border-soft rounded-xl p-4 text-sm font-bold text-theme-primary focus:outline-none focus:border-theme-accent transition-colors min-h-[44px]"
                />
              </div>

              <div>
                <label className="block text-xs font-black text-theme-muted uppercase tracking-wider mb-2">Business Type</label>
                <select 
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                  className="w-full bg-theme-app border border-theme-border-soft rounded-xl p-4 text-sm font-bold text-theme-primary focus:outline-none focus:border-theme-accent transition-colors min-h-[44px]"
                >
                  {BUSINESS_PRESETS.map(preset => (
                    <option key={preset.id} value={preset.id}>{preset.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-black text-theme-muted uppercase tracking-wider mb-3">Enabled Modules</label>
                <div className="space-y-2">
                  {ALL_MODULES.map(mod => (
                    <div 
                      key={mod.id} 
                      onClick={() => toggleModule(mod.id)}
                      className={`flex items-center justify-between p-4 rounded-xl border cursor-pointer transition-colors ${enabledModules.includes(mod.id) ? 'bg-theme-accent/5 border-theme-accent/30' : 'bg-theme-app border-theme-border-soft'}`}
                    >
                      <span className="font-bold text-sm text-theme-primary">{mod.name}</span>
                      {enabledModules.includes(mod.id) ? (
                        <CheckCircle2 className="w-5 h-5 text-theme-accent" />
                      ) : (
                        <Circle className="w-5 h-5 text-theme-muted" />
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => setIsAdding(false)}
                className="flex-1 py-4 bg-theme-app text-theme-muted font-black rounded-2xl border border-theme-border-soft hover:text-theme-primary transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={handleSave}
                disabled={!name.trim()}
                className="flex-1 py-4 bg-[image:var(--accent-gradient)] text-white font-black rounded-2xl shadow-premium disabled:opacity-50 disabled:cursor-not-allowed transition-all"
              >
                Save Workspace
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
    </AnimatedPage>
  );
};

export default WorkspaceManager;

import React, { useState, useEffect, memo } from 'react';
import { motion } from 'framer-motion';
import { 
  Users, CreditCard, Activity, Crown, Cloud, IndianRupee, 
  ShieldAlert, CheckCircle2, TrendingUp, AlertTriangle, Layers, Building2, 
  UserPlus, FileWarning 
} from 'lucide-react';
import { adminEngine } from '../../services/adminEngine';
import { pageVariants } from '../../utils/animations';
import { KPISkeleton } from '../../components/PremiumSkeleton';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/Card';
import { Progress, ProgressRing } from '../../components/ui/Progress';
import { Badge } from '../../components/ui/Badge';
import { Button } from '../../components/ui/Button';

const AdminDashboard = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalUsers: 0, activeUsers: 0, premiumUsers: 0, freeUsers: 0, todayNewUsers: 0,
    totalWorkspaces: 0, activeWorkspaces: 0,
    monthlyRevenue: 0, pendingPayments: 0, pendingPaymentProofs: 0,
    failedSyncs: 0, cloudStorageUsage: '0 GB',
    systemHealth: 'Healthy',
    totalInvoices: 0, totalCustomers: 0, totalProducts: 0
  });
  const [recentActivities, setRecentActivities] = useState([]);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const users = await adminEngine.getUsersList();
        const proofs = await adminEngine.getPaymentProofs();
        const revs = await adminEngine.getRevenueStates();
        const extraStats = await adminEngine.getTotalStats();

        const totalUsers = users.length;
        const premiumUsers = users.filter(u => u.planStatus === 'premium').length;
        const freeUsers = totalUsers - premiumUsers;

        let totalWorkspaces = 0;
        users.forEach(u => { totalWorkspaces += (u.workspacesCount || 1); });

        const activeWorkspaces = users.filter(u => !u.blocked).length || Math.floor(totalWorkspaces * 0.85);
        const activeUsers = users.filter(u => !u.blocked).length || Math.floor(totalUsers * 0.75);

        const today = new Date().toISOString().split('T')[0];
        const todayNewUsers = users.filter(u => (u.createdAt || '').startsWith(today)).length;

        const pendingPaymentProofs = proofs.filter(p => p.status === 'Pending').length;
        const pendingPayments = proofs.filter(p => p.status === 'Pending').reduce((acc, p) => acc + (parseFloat(p.amount) || 0), 0);

        const monthlyRevenue = revs.reduce((acc, r) => acc + (parseFloat(r.platformPaidAmount) || 0), 0);

        // Build recent activities dynamically from real data
        const activities = [];

        // Add latest users
        const sortedUsers = [...users].sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0)).slice(0, 5);
        sortedUsers.forEach(u => {
          activities.push({
            id: `usr_${u.id}`,
            type: 'user',
            title: 'New user registered',
            desc: `User ${u.email} created an account.`,
            date: new Date(u.createdAt || Date.now()),
            icon: UserPlus,
            color: 'theme-accent'
          });
        });

        // Add latest payment proofs
        const sortedProofs = [...proofs].sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0)).slice(0, 5);
        sortedProofs.forEach(p => {
          activities.push({
            id: `prf_${p.id}`,
            type: 'payment',
            title: 'Payment Proof Uploaded',
            desc: `₹${p.amount} pending verification for workspace ${p.workspaceId || 'Unknown'}.`,
            date: new Date(p.createdAt || Date.now()),
            icon: CreditCard,
            color: 'theme-warning'
          });
        });

        activities.sort((a, b) => b.date - a.date);

        setRecentActivities(activities.slice(0, 8));

        setStats({
          totalUsers, activeUsers, premiumUsers, freeUsers, todayNewUsers,
          totalWorkspaces, activeWorkspaces, monthlyRevenue, pendingPayments, pendingPaymentProofs,
          failedSyncs: 0,
          cloudStorageUsage: `${(totalWorkspaces * 0.05).toFixed(2)} GB`,
          systemHealth: navigator.onLine ? 'Healthy' : 'Offline',
          totalInvoices: extraStats.invoices,
          totalCustomers: extraStats.customers,
          totalProducts: extraStats.products
        });
      } catch (e) {
        console.error('Admin stat error:', e);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  if (loading) {
    return (
      <div className="space-y-8">
        <div className="mb-6"><h2 className="text-2xl font-black text-theme-primary">Dashboard Overview</h2></div>
        <KPISkeleton count={12} />
      </div>
    );
  }

  const kpiCards = [
    { label: 'Total Users', value: stats.totalUsers, icon: Users, color: 'theme-primary' },
    { label: 'Premium Users', value: stats.premiumUsers, icon: Crown, color: 'theme-accent' },
    { label: "Today's New", value: stats.todayNewUsers, icon: TrendingUp, color: 'theme-success' },
    { label: 'Workspaces', value: stats.totalWorkspaces, icon: Building2, color: 'theme-primary' },
    { label: 'Total Invoices', value: stats.totalInvoices || 0, icon: Layers, color: 'theme-accent' },
    { label: 'Total Revenue', value: `₹${stats.monthlyRevenue}`, icon: IndianRupee, color: 'theme-success' },
    { label: 'Pending Dues', value: `₹${stats.pendingPayments}`, icon: AlertTriangle, color: 'theme-warning' },
    { label: 'Payment Proofs', value: stats.pendingPaymentProofs, icon: CreditCard, color: 'theme-danger' },
    { label: 'Storage Usage', value: stats.cloudStorageUsage, icon: Cloud, color: 'theme-primary' },
    { label: 'Offline Queue', value: stats.failedSyncs, icon: FileWarning, color: stats.failedSyncs > 0 ? 'theme-danger' : 'theme-muted' },
  ];

  return (
    <motion.div variants={pageVariants} initial="initial" animate="animate" className="space-y-8 pb-32">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
        <div>
          <h2 className="text-3xl font-black text-theme-primary tracking-tight">Owner Dashboard</h2>
          <p className="text-sm text-theme-secondary mt-1">Real-time global metrics for BillQyro platform.</p>
        </div>

        <div className="flex items-center gap-3">
          <Badge variant={stats.systemHealth === 'Healthy' ? 'success' : 'danger'} className="px-4 py-2 text-sm">
            {stats.systemHealth === 'Healthy' ? <CheckCircle2 className="w-4 h-4 mr-2" /> : <ShieldAlert className="w-4 h-4 mr-2" />}
            System {stats.systemHealth}
          </Badge>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
        {kpiCards.map((kpi, index) => (
          <motion.div 
            key={index}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.05 }}
          >
            <Card className="h-full hover:scale-[1.02] transition-transform flex flex-col justify-between border-transparent bg-gradient-to-br from-theme-surface to-theme-surface-hover shadow-sm">
              <CardContent className="p-5">
                <div className="flex items-center justify-between mb-4">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-theme-muted">{kpi.label}</span>
                  <kpi.icon className={`w-4 h-4 text-${kpi.color}`} />
                </div>
                <div className="text-2xl font-black text-theme-primary">{kpi.value}</div>
              </CardContent>
            </Card>
          </motion.div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Growth Rings */}
        <Card className="lg:col-span-1">
          <CardHeader>
            <CardTitle>System Health</CardTitle>
          </CardHeader>
          <CardContent className="flex flex-col items-center justify-center space-y-8 py-8">
            <ProgressRing value={99.9} max={100} size={160} strokeWidth={10} color="var(--success)" label="99.9%" sublabel="Cloud Sync Uptime" />

            <div className="w-full space-y-4">
              <div>
                <div className="flex justify-between text-xs font-bold text-theme-secondary mb-1">
                  <span>Premium Conversion</span>
                  <span>{stats.totalUsers > 0 ? ((stats.premiumUsers / stats.totalUsers) * 100).toFixed(1) : 0}%</span>
                </div>
                <Progress value={stats.premiumUsers} max={stats.totalUsers} />
              </div>
              <div>
                <div className="flex justify-between text-xs font-bold text-theme-secondary mb-1">
                  <span>Storage Capacity</span>
                  <span>45%</span>
                </div>
                <Progress value={45} max={100} colorClass="bg-theme-warning" shadowClass="shadow-[0_0_10px_var(--warning)]" />
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Recent Activities */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="flex items-center gap-2">
                <Activity className="w-5 h-5 text-theme-accent" /> Recent Activities
              </CardTitle>
              <Button variant="outline" size="sm">View All Logs</Button>
            </div>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {recentActivities.map((act) => (
                <div key={act.id} className="flex items-start gap-4 p-4 rounded-xl bg-theme-surface-elevated border border-theme-border-soft hover:border-theme-accent/30 transition-colors">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 bg-${act.color}/10 text-${act.color}`}>
                    <act.icon className="w-5 h-5" />
                  </div>
                  <div className="flex-1">
                    <div className="flex justify-between items-start">
                      <p className="text-sm font-bold text-theme-primary">{act.title}</p>
                      <span className="text-[10px] text-theme-muted whitespace-nowrap">
                        {act.date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    <p className="text-xs text-theme-secondary mt-1">{act.desc}</p>
                  </div>
                </div>
              ))}
              {recentActivities.length === 0 && (
                <div className="text-center py-8 text-theme-muted text-sm font-medium">No recent activities found.</div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </motion.div>
  );
};

export default memo(AdminDashboard);

