  if (s === 'Picked Up') return 'text-blue-500';
  if (s === 'Pending') return 'text-orange-500';
  return 'text-red-500';
};
const si = (s) => {
  if (s === 'Delivered') return CheckCircle;
  if (s === 'Out for Delivery' || s === 'In Transit') return Truck;
