import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Briefcase, Plus, Search, Trash2, Edit2, Calendar, DollarSign, User, CheckCircle, Clock, AlertTriangle } from 'lucide-react';
