              <button onClick={() => handleSpeak(legalTextHindi, 'hi-IN')} className="text-[10px] bg-theme-danger/10 text-theme-danger px-3 py-1.5 rounded-full font-bold hover:bg-theme-danger/20 flex items-center gap-1">
