                          >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-[0_1px_3px_rgba(0,0,0,0.3)] transition-transform duration-500 ease-in-out ${(globalSettings?.maintenanceMode) ? 'translate-x-5' : 'translate-x-0'}`}></div>
                          </button>
                        </div>
