            >
              <Icon className={`w-5 h-5 shrink-0 ${isSelected ? 'text-white' : 'text-theme-muted'}`} />
              <span className={`text-xs font-black tracking-wide uppercase ${isSelected ? 'text-white' : 'text-theme-muted'}`}>
                {tab.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

