const DEFAULT_WIDGETS = [
  { id: 'revenueOverview', label: 'Revenue Overview (Chart)', visible: true },
  { id: 'recentInvoices', label: 'Recent Invoices List', visible: true },
  { id: 'pendingPayments', label: 'Pending Payments Alerts', visible: true },
