  if (!localStorage.getItem(KEYS.PRODUCTS)) {
    localStorage.setItem(KEYS.PRODUCTS, JSON.stringify([]));
  }
  
  if (!localStorage.getItem(KEYS.AUTH)) {
    // Session is handled by App.jsx now
  }
  
