export const updatePlatformPaymentProofStatus = async (proofId, status, adminNote = '', invoices = []) => {
  let matchedProof = null;

  if (firebaseReady) {
    const proofRef = doc(db, 'platformPaymentProofs', proofId);
    const proofSnap = await getDoc(proofRef);
    if (proofSnap.exists()) {
      matchedProof = proofSnap.data();
      // Prevent duplicate actions
      if (matchedProof.status === 'Approved' || matchedProof.status === 'Verified') {
        throw new Error('This proof has already been verified.');
      }
      if (matchedProof.status === 'Rejected') {
        throw new Error('This proof has already been rejected.');
      }
    }
  }

  // Local storage update
  try {
    const cached = JSON.parse(localStorage.getItem('billqyro_platform_payment_proofs') || '[]');
    const idx = cached.findIndex(p => p.id === proofId);
    if (idx !== -1) {
      cached[idx].status = status;
      cached[idx].adminNote = adminNote;
      cached[idx].updatedAt = new Date().toISOString();
      matchedProof = cached[idx];
      localStorage.setItem('billqyro_platform_payment_proofs', JSON.stringify(cached));
    }
  } catch (e) { console.warn('Error updating cached payment proof status', e); }

  if (firebaseReady) {
    try {
      const proofRef = doc(db, 'platformPaymentProofs', proofId);

      await setDoc(proofRef, {
        status,
        adminNote,
        updatedAt: new Date().toISOString()
      }, { merge: true });
    } catch (e) {
      console.error('Failed to update proof status in Firestore', e);
      return false;
    }
  }

  if (!matchedProof) return false;

  // If approved, add paid amount to user's platformPaidAmount
  if (status === 'Approved') {
    const { userId, amount } = matchedProof;
    const globalSettings = await getGlobalRevenueSettings();
    let currentPaid = 0;

    try {
      const stateStr = localStorage.getItem(`billqyro_user_revenue_state_${userId}`);
      if (stateStr) {
        currentPaid = parseFloat(JSON.parse(stateStr).platformPaidAmount) || 0;
      }
    } catch (e) { console.warn('Error reading cached user revenue state', e); }

    if (firebaseReady) {
      try {
        const userRef = doc(db, 'platformRevenue', userId);
        const userSnap = await getDoc(userRef);
        if (userSnap.exists()) {
          currentPaid = parseFloat(userSnap.data().platformPaidAmount) || 0;
        }
      } catch (e) { console.warn('Error reading Firestore platform revenue', e); }
    }

    const newPaidAmount = currentPaid + amount;

    let userInvoices = invoices;
    if ((!userInvoices || userInvoices.length === 0) && firebaseReady) {
      try {
        const snap = await getDocs(collection(db, 'invoices', userId, 'items'));
        userInvoices = [];
        snap.forEach(d => userInvoices.push(d.data()));
      } catch (e) {
        console.error('Failed to fetch user invoices for dues recalculation:', e);
      }
    }

    const recalculated = calculateUserRevenueState(userId, userInvoices, globalSettings, { status: 'free' }, newPaidAmount);
    recalculated.lastPlatformPaymentDate = new Date().toISOString();

    await saveUserRevenueState(userId, recalculated);
  }

  return true;
};

import { invoiceEngine } from './invoiceEngine';
import * as dbEngine from './dbEngine';
import {  verifyCustomerPortal as dbVerifyCustomerPortal  } from './dbEngine';
import { paymentEngine } from './paymentEngine';

class PortalEngine {
  // Public invoice access
  async getPublicInvoice(invoiceId) {
    // In production, this would query a dedicated public endpoint or verify tokens.
    // For now, it delegates to invoiceEngine which reads from dbEngine
    return await invoiceEngine.getInvoiceById(invoiceId);
  }

  // Upload payment proof from customer portal
  async submitPaymentProof(invoiceId, uploadData) {
    // uploadData: { amount, method, file/url, notes }
    return await paymentEngine.recordPaymentProof(invoiceId, uploadData);
  }

  // Approve a quotation from customer portal
  async approveQuotation(invoiceId, signatureData) {
    const invoice = await invoiceEngine.getInvoiceById(invoiceId);
    if (!invoice) throw new Error("Invoice/Quotation not found");

    if (invoice.type === 'Quotation' || invoice.type === 'Estimate') {
      invoice.status = 'Approved';
      invoice.signature = signatureData;
      invoice.updatedAt = new Date().toISOString();
      return await invoiceEngine.saveInvoice(invoice);
    }
    throw new Error("Document is not a quotation or estimate");
  }

  // Reject a quotation from customer portal
  async rejectQuotation(invoiceId, reason) {
    const invoice = await invoiceEngine.getInvoiceById(invoiceId);
    if (!invoice) throw new Error("Invoice/Quotation not found");

    if (invoice.type === 'Quotation' || invoice.type === 'Estimate') {
      invoice.status = 'Rejected';
      invoice.rejectionReason = reason;
      invoice.updatedAt = new Date().toISOString();
      return await invoiceEngine.saveInvoice(invoice);
    }
    throw new Error("Document is not a quotation or estimate");
  }

  // Get customer's ledger for the portal (requires authentication/token)
  async getCustomerPortalData(customerId) {
